/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A52 staging patch: exact frozen manifest emigrate–inch (80 entries). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs});
P('emigrate','Emigrate 来自拉丁语 emigrare，由 ex-“离开”与 migrare“迁移”构成，指离开自己的国家到另一国定居。',C('emigrate.s1','迁居与国界','After receiving a job offer abroad, Lina decided to emigrate from Chile and begin a new life in Canada.','收到海外工作邀请后，莉娜决定移居国外，从智利搬到加拿大开始新生活。','After receiving a job offer abroad / Lina decided to emigrate from Chile / and begin a new life in Canada.','emigrate from 指离开某国迁居；from 标出出发地。','句子明确写出离开智利并到加拿大定居。'),M('Lina emigrated to Chile when she left Chile to settle in Canada.','Lina emigrated from Chile when she left Chile to settle in Canada.','emigrate from 后接离开的国家，不能用 to 指出发地。','collocation'),[Q('emigrate',1,1,'To emigrate from a country is to?','leave it to live in another country','visit it for a short holiday','return to it after a brief trip','emigrate 表示离开本国迁往他国定居。'),Q('emigrate',2,1,'Which sentence uses emigrate correctly?','They emigrated from Peru to Spain.','They emigrated at Peru for a weekend.','They emigrated Peru after returning home.','常用结构是 emigrate from A to B。'),Q('emigrate',3,1,'A family that emigrates is making a move that is usually?','a change of country for residence','a trip between rooms in one house','a daily commute to a nearby office','该词强调移居到另一个国家。'),Q('emigrate',4,1,'Which word describes arriving in the new country?','immigrate','emigrate','hibernate','emigrate 描述离开，immigrate 描述迁入。')]);
P('fertility','Fertility 来自拉丁语 fertilis“丰产的”，可指土壤肥沃、生育能力，或产生许多创意与作品的多产能力。',[C('fertility.s1','农业与土壤','The farmer improved the field’s fertility by adding compost and planting a cover crop between harvests.','农夫通过施用堆肥并在两次收获间种植覆盖作物，提高了田地的肥力。','The farmer improved the field’s fertility / by adding compost / and planting a cover crop between harvests.','fertility 指土壤帮助作物生长的肥沃程度；by 引出改良方法。','堆肥和覆盖作物改善土壤生产力。'),C('fertility.s2','生殖健康','The specialist discussed fertility with the couple and explained which tests could assess their ability to conceive.','专科医生与这对伴侣讨论生育力，并解释哪些检查可以评估他们的受孕能力。','The specialist discussed fertility with the couple / and explained which tests / could assess their ability to conceive.','fertility 指人或动物生育后代的能力；which 从句说明检查内容。','评估受孕能力对应生育力义。'),C('fertility.s3','创作与艺术','The director praised the playwright’s fertility of invention, noting how many original characters appeared in each new script.','导演称赞剧作家的创意多产，指出每份新剧本里都有许多原创角色。','The director praised the playwright’s fertility of invention / noting how many original characters / appeared in each new script.','fertility of invention 是比喻用法，指创意丰富、多产；noting 补充赞赏理由。','原创角色持续涌现体现创作多产。')],M('The soil had high fertility because it lacked nutrients and could not support the crops.','The soil had low fertility because it lacked nutrients and could not support the crops.','缺乏养分、无法支持作物说明土壤肥力低。'),[Q('fertility',1,1,'Soil fertility is its ability to?','support healthy plant growth','prevent all seeds from sprouting','turn crops into stone','s1 指土壤肥沃程度。'),Q('fertility',2,2,'A medical discussion of fertility concerns the ability to?','have offspring','grow crops in poor soil','write many plays','s2 指生育能力。'),Q('fertility',3,3,'A writer’s fertility of invention means the writer?','produces many original ideas','cannot think of any character','copies every story exactly','s3 比喻创意丰富、多产。'),Q('fertility',4,1,'What would most directly improve a field’s fertility?','adding compost to nutrient-poor soil','removing all organic matter','covering the field with concrete','堆肥可增加土壤肥力。')]);
P('fertilization','Fertilization 由 fertilize 加 -ation 构成，可指精子与卵子或花粉与胚珠结合的受精，也可指向土壤施肥。',[C('fertilization.s1','生物与繁殖','In flowering plants, fertilization follows pollination when a pollen cell joins with an ovule inside the flower.','在开花植物中，授粉之后花粉细胞与花内胚珠结合，完成受精。','In flowering plants / fertilization follows pollination / when a pollen cell joins with an ovule inside the flower.','fertilization 指生殖细胞结合；when 从句说明过程发生的条件。','花粉细胞与胚珠结合对应植物受精义。'),C('fertilization.s2','园艺与土壤','The greenhouse schedule includes fertilization of the beds before seedlings are moved into the soil.','温室计划包括在幼苗移入土壤前给苗床施肥。','The greenhouse schedule includes fertilization of the beds / before seedlings are moved / into the soil.','fertilization of the beds 指给苗床施肥；before 标出施肥与移栽的顺序。','向苗床施加肥料是农业义。')],M('The textbook said fertilization of the ovule meant adding compost to the garden soil.','The textbook said fertilization of the ovule meant the joining of a male cell with the ovule.','胚珠受精指生殖细胞结合，不是给土壤施肥。'),[Q('fertilization',1,1,'In reproduction, fertilization is?','the joining of a sperm and an egg, or pollen and an ovule','the removal of nutrients from soil','the harvesting of mature fruit','s1 指生殖细胞结合。'),Q('fertilization',2,2,'In gardening, fertilization means?','applying fertilizer to soil','joining a pollen cell to an ovule','moving seedlings into a greenhouse','s2 指施肥。'),Q('fertilization',3,1,'Which event is plant fertilization?','a pollen cell joins with an ovule','a farmer spreads compost over a bed','a flower opens in sunlight','花粉与胚珠结合属于受精。'),Q('fertilization',4,2,'The gardener scheduled fertilization before planting seedlings. What was planned?','adding nutrients to the soil','testing whether an egg was fertilized','harvesting the crop','园艺场景中 fertilization 指施肥。')]);
P('fertilize','Fertilize 与 fertile 同源，来自拉丁语 fertilis“丰产的”，可表示给土壤施肥，也可表示使卵细胞或胚珠受精。',[C('fertilize.s1','园艺与施肥','The gardener fertilized the rose beds with a measured dose of compost before the spring growth began.','春季生长开始前，园丁按量给玫瑰花坛施了堆肥。','The gardener fertilized the rose beds / with a measured dose of compost / before the spring growth began.','fertilize the beds 表示给花坛施肥；with 引出所用肥料。','堆肥施入花坛是改善土壤的做法。'),C('fertilize.s2','植物繁殖','A bee can carry pollen from one flower and fertilize an ovule in another flower of the same species.','蜜蜂可以把花粉从一朵花带到同种植物的另一朵花，使胚珠受精。','A bee can carry pollen from one flower / and fertilize an ovule / in another flower of the same species.','fertilize an ovule 表示使胚珠受精；and 连接传粉与受精的作用。','花粉到达胚珠后可完成受精。')],M('The gardener fertilized the beds by removing nutrients and leaving the soil less able to support plants.','The gardener fertilized the beds by adding compost to improve the soil.','移除养分会削弱土壤，不是施肥。'),[Q('fertilize',1,1,'To fertilize a garden bed is to?','add nutrients to its soil','remove every seed from it','harvest all of its flowers','s1 指施肥。'),Q('fertilize',2,2,'In plant reproduction, pollen can fertilize?','an ovule','the garden path','a mature leaf','s2 指使胚珠受精。'),Q('fertilize',3,1,'Which action fertilizes a field?','spreading compost to improve the soil','pulling all nutrients out of the earth','picking ripe fruit from the trees','施用堆肥是给田地施肥。'),Q('fertilize',4,2,'A pollen cell fertilizes an ovule when it?','joins with it in the reproductive process','is mixed into compost','falls onto a leaf without reaching it','受精指生殖细胞结合。')]);
P('fertilizer','Fertilizer 由 fertilize 加 -er 构成，通常指农民施入土壤以供给作物养分的肥料，也可比喻任何促进发展的因素。',[C('fertilizer.s1','农业与作物','The cooperative bought organic fertilizer to replace nutrients removed from the fields by repeated harvests.','合作社购买有机肥料，以补充多次收获从田里带走的养分。','The cooperative bought organic fertilizer / to replace nutrients / removed from the fields by repeated harvests.','fertilizer 是供给土壤养分的物质；to 引出购买目的。','肥料用来补充作物生长所需养分。'),C('fertilizer.s2','比喻与成长','Constructive disagreement became a fertilizer for the research team’s ideas, pushing members to test stronger explanations.','建设性的分歧成了研究团队创意的催化剂，促使成员检验更有力的解释。','Constructive disagreement became a fertilizer for the research team’s ideas / pushing members / to test stronger explanations.','fertilizer 可比喻促进成长的事物；for 表示被促进的对象。','分歧推动想法成长，属于比喻义。')],M('The farm spread fertilizer to remove nutrients from the soil and prevent crops from growing.','The farm spread fertilizer to add nutrients to the soil and support crop growth.','肥料供给养分，而非移除养分。'),[Q('fertilizer',1,1,'Farmers use fertilizer mainly to?','add nutrients to soil for crops','remove all water from a field','make seeds stop developing','s1 指农业肥料。'),Q('fertilizer',2,2,'A “fertilizer for ideas” is something that?','encourages ideas to develop','prevents anyone from thinking','measures the length of a field','s2 是促进成长的比喻。'),Q('fertilizer',3,1,'Which item can be fertilizer?','compost added to soil','a label placed on a seed packet','a tool used only to harvest fruit','堆肥可以作为肥料。'),Q('fertilizer',4,2,'Constructive disagreement was called a fertilizer because it?','helped the team develop stronger ideas','ended all discussion without thought','replaced the team’s research notes','分歧促进了想法的发展。')]);
P('fervid','Fervid 来自拉丁语 fervidus、源自 fervere“沸腾”，形容热烈、充满激情的情绪或表达。',C('fervid.s1','演讲与热忱','The activist gave a fervid defense of the library, arguing that every neighborhood deserved a safe place to read.','这位活动人士热情洋溢地为图书馆辩护，主张每个社区都应有安全的阅读场所。','The activist gave a fervid defense of the library / arguing that every neighborhood / deserved a safe place to read.','fervid 修饰 defense，表示充满激情；arguing 补充演讲主张。','激昂地捍卫社区图书馆体现热烈情感。'),M('Her fervid speech was delivered in a bored, indifferent tone that showed no strong feeling.','Her fervid speech was delivered with intense enthusiasm and strong feeling.','冷淡无感的表达与 fervid 的热情相反。'),[Q('fervid',1,1,'A fervid speech is delivered with?','intense passion or enthusiasm','complete boredom and indifference','careful silence and no emotion','fervid 描述强烈热情。'),Q('fervid',2,1,'Which speaker sounds fervid?','one who passionately defends a cause','one who reads a list without feeling','one who refuses to discuss the topic','热情捍卫主张体现 fervid。'),Q('fervid',3,1,'Fervid is closest in meaning to?','impassioned','inactive','inaccurate','fervid 与充满激情的意思相近。'),Q('fervid',4,1,'A fervid defense of a library would likely be?','a passionate argument for its value','a quiet inventory of its chairs','a plan to remove every book','fervid 强调强烈热情。')]);
P('fester','Fester 可能与中古英语及日耳曼语族中表示脓疮、腐烂的词有关，可指伤口化脓、怨恨持续恶化，也可作名词指感染的疮口。',[C('fester.s1','伤口与感染','The untreated cut began to fester, becoming swollen and painful as infection spread beneath the skin.','未经处理的伤口开始化脓，皮下感染扩散后变得肿胀疼痛。','The untreated cut began to fester / becoming swollen and painful / as infection spread beneath the skin.','fester 作动词表示伤口感染化脓；as 引出恶化过程。','肿痛并有感染扩散说明伤口溃烂。'),C('fester.s2','冲突与怨恨','Because the neighbors never discussed the boundary dispute, resentment continued to fester for years.','邻居们从未谈论边界争端，怨恨因此持续多年并愈积愈深。','Because the neighbors never discussed the boundary dispute / resentment continued to fester / for years.','fester 可比喻怨恨在暗中持续恶化；because 引出矛盾长期存在的原因。','未解决的怨恨长时间加深。'),C('fester.s3','医学描述','The nurse cleaned the small fester on the patient’s heel and covered it with a sterile dressing.','护士清理了病人脚跟上的小脓疮，并用无菌敷料包扎。','The nurse cleaned the small fester / on the patient’s heel / and covered it with a sterile dressing.','fester 作名词时指感染的疮口；and 连接处理步骤。','需要清理和包扎的感染疮口对应名词义。')],M('The wound began to fester as it healed cleanly, with no infection, swelling, or discharge.','The wound began to heal cleanly, with no infection, swelling, or discharge.','没有感染、肿胀或流脓表示伤口在愈合，而非化脓。'),[Q('fester',1,1,'A wound that festers?','becomes infected and may produce pus','heals completely without infection','turns into a bone','s1 指伤口感染化脓。'),Q('fester',2,2,'Resentment that festers?','grows worse while remaining unresolved','disappears after a sincere apology','becomes a written boundary map','s2 是怨恨持续恶化的比喻。'),Q('fester',3,3,'A fester can be?','an infected sore','a festive public celebration','a unit of agricultural fertilizer','s3 作名词指脓疮。'),Q('fester',4,2,'Why can avoiding a dispute let resentment fester?','the unresolved grievance may grow worse over time','silence automatically solves every disagreement','the people forget the issue at once','未处理的怨恨可能随时间加深。')]);
P('festive','Festive 来自拉丁语 festivus“节庆的、欢乐的”，形容具有节日气氛、明亮喜庆的场景或装饰。',C('festive.s1','庆典与装饰','Colorful lanterns and music gave the town square a festive atmosphere before the winter parade.','冬季游行前，五彩灯笼和音乐让镇广场充满节日气氛。','Colorful lanterns and music / gave the town square / a festive atmosphere before the winter parade.','festive 修饰 atmosphere，表示节庆欢乐；before 标明布置时间。','灯笼、音乐和游行营造喜庆氛围。'),M('The room felt festive because it was bare, silent, and decorated for no celebration.','The room felt festive because lanterns, music, and bright decorations filled it.','空荡寂静且没有庆典装饰，不显喜庆。'),[Q('festive',1,1,'A festive atmosphere is?','bright and joyful like a celebration','silent and gloomy with no decoration','a period of unpaid debt','festive 表示节日的、喜庆的。'),Q('festive',2,1,'Which detail can make a square feel festive?','lanterns and music before a parade','empty benches under a dark sky','a closed shop on an ordinary morning','灯笼和音乐营造节庆氛围。'),Q('festive',3,1,'Festive is commonly used to describe?','decorations, clothing, or an atmosphere for a celebration','a legal rule that is currently active','a medical ability to reproduce','该词常描述庆祝场景或装饰。'),Q('festive',4,1,'The adjective festive is related to?','a feast or celebration','a feud between families','a unit of length','festive 源自与节庆相关的拉丁词。')]);
P('fete','Fete（亦作带法语重音符号的 fête）来自法语 fête“节日”，可指户外公众游乐会，也可作动词表示盛情款待、隆重庆祝某人。',[C('fete.s1','社区活动','The school held a summer fete with food stalls and games to raise money for the new playground.','学校举办夏季游乐会，设有食品摊位和游戏，为新操场筹款。','The school held a summer fete / with food stalls and games / to raise money for the new playground.','fete 作名词指户外公众娱乐活动；to 引出举办活动的目的。','摊位与游戏组成筹款游乐会。'),C('fete.s2','款待与表彰','After the expedition returned, the village feted the research team with a dinner and a public ceremony.','考察队返回后，村民以晚宴和公开仪式盛情款待并庆祝他们。','After the expedition returned / the village feted the research team / with a dinner and a public ceremony.','fete 作动词表示以庆典款待或表彰；with 引出庆祝方式。','晚宴与仪式是迎接和表彰团队的活动。')],M('The village feted the visitors by ignoring their arrival and refusing to offer any welcome.','The village feted the visitors with a welcoming dinner and public celebration.','冷落来访者并拒绝欢迎与盛情款待相反。'),[Q('fete',1,1,'A school fete is usually?','an outdoor public event with entertainment','a private debt agreement','an indoor medical examination','s1 指户外公众游乐会。'),Q('fete',2,2,'To fete a returning team is to?','honor it with celebration and hospitality','charge it with a crime','make it leave the country','s2 指盛情款待或庆祝。'),Q('fete',3,1,'Which event could be a fete?','a community fair with food stalls and games','a quiet individual reading lesson','a court hearing about a boundary','社区集市式活动可称 fete。'),Q('fete',4,2,'The village feted the explorers after their return. What did it do?','celebrated and welcomed them warmly','ignored them and closed the hall','asked them to move overseas','动词 fete 表示庆祝并热情款待。')]);
P('fetish','Fetish 经葡萄牙语 feitiço“护符、人工制品”进入英语，原指被认为有灵力的物件，现可指受到非理性崇拜或过度迷恋的对象。',C('fetish.s1','物件与崇拜','The collector treated the cracked stone as a fetish, believing it had protective powers despite having no evidence.','收藏者把裂纹石头当作护符崇拜，尽管没有证据证明它具有保护力量。','The collector treated the cracked stone as a fetish / believing it had protective powers / despite having no evidence.','fetish 指被赋予超自然力量或受到非理性崇拜的物件；despite 引出缺乏证据的反差。','收藏者相信石头有护佑力并非理性证据。'),M('The collector called the stone a fetish because she regarded it as an ordinary rock with no special power or devotion.','The collector called the stone a fetish because she irrationally believed it had protective powers.','毫无特殊崇拜或力量信念的普通石头不符合这里的 fetish 义。'),[Q('fetish',1,1,'A fetish can be an object that someone?','irrationally believes has special power or treats with devotion','uses only to measure a field','knows has no meaning and ignores','fetish 可指被赋予力量、受到崇拜的物件。'),Q('fetish',2,1,'Why was the collector’s stone called a fetish?','she believed it protected her without evidence','it was a standard farming fertilizer','it was a document proving identity','无证据地相信它有护佑力体现 fetish。'),Q('fetish',3,1,'Which description best fits the source sense of fetish?','an object of irrational devotion','a public outdoor fair','a long family quarrel','它指非理性崇拜的对象。'),Q('fetish',4,1,'A person who treats an ordinary object as a fetish may?','attach extraordinary power or devotion to it','use it only for its ordinary practical function','throw it away without noticing it','fetish 涉及对物件的过度崇拜或赋能。')]);
P('fetishism','Fetishism 由 fetish 加 -ism 构成，指对物件、商品或某种做法的非理性崇拜。',C('fetishism.s1','消费与崇拜','The essay criticizes brand fetishism, in which buyers treat a logo as proof of quality without examining the product.','这篇文章批评品牌崇拜：消费者不检查商品本身，就把商标当作质量保证。','The essay criticizes brand fetishism / in which buyers treat a logo as proof of quality / without examining the product.','fetishism 指对品牌的非理性崇拜；in which 解释这种行为如何表现。','只因商标便认定质量，体现盲目崇拜。'),M('The article called it fetishism because customers carefully compared product quality and refused to value logos alone.','The article called it brand fetishism because customers treated a logo as proof of quality without checking the goods.','认真比较产品、拒绝只看标志，与盲目崇拜相反。'),[Q('fetishism',1,1,'Fetishism is?','irrational devotion to an object, goods, or a practice','a careful comparison based on evidence','a public celebration with stalls','fetishism 指非理性崇拜。'),Q('fetishism',2,1,'Brand fetishism occurs when buyers?','assume a logo guarantees quality without checking the product','compare materials and performance carefully','buy an item only because it is affordable','只凭标志认定质量属于品牌崇拜。'),Q('fetishism',3,1,'Which behavior suggests fetishism of a practice?','treating one routine as magically effective despite contrary evidence','testing several methods against results','changing a routine when it fails','无视反证仍盲目崇拜某做法。'),Q('fetishism',4,1,'Fetishism is formed from fetish plus a suffix meaning?','a state or system of belief','a person who performs a task','a small unit of length','-ism 常构成状态或思想体系名词。')]);
P('fetter','Fetter 来自古英语中表示脚镣的词，可作名词指锁住囚犯双脚的链条，也可作动词或比喻名词表示束缚自由、限制发展。',[C('fetter.s1','监禁与束缚','The guard removed the iron fetters from the prisoner’s ankles after the court ordered his release.','法院下令释放后，守卫取下了囚犯脚踝上的铁镣。','The guard removed the iron fetters / from the prisoner’s ankles / after the court ordered his release.','fetters 作名词复数，指锁住双脚的镣铐；from 标明取下的位置。','铁链套在脚踝上，是实体脚镣。'),C('fetter.s2','自由与限制','Outdated rules fetter the clinic’s ability to respond quickly when a new disease appears.','过时规定限制了诊所在新疾病出现时迅速应对的能力。','Outdated rules fetter the clinic’s ability to respond quickly / when a new disease appears.','fetter 作动词表示限制自由或行动能力；when 引出受限情境。','规定妨碍诊所快速应对，体现束缚义。'),C('fetter.s3','进步与障碍','A lack of reliable data became a fetter on the project, delaying decisions at every stage.','缺少可靠数据成了项目的桎梏，使每个阶段的决策都被拖延。','A lack of reliable data became a fetter on the project / delaying decisions / at every stage.','fetter 作比喻名词，指阻碍自由或进展的事物；on 指被限制的对象。','数据缺乏阻碍项目推进。')],M('The chain fettered the prisoner by giving him complete freedom to run away.','The chain fettered the prisoner by restricting his movement.','脚镣限制行动，而不是给予自由。'),[Q('fetter',1,1,'A prisoner’s fetters are?','chains that restrain the feet','papers proving identity','fertilizer for a field','s1 指脚镣。'),Q('fetter',2,2,'Rules fetter an organization when they?','restrict its freedom or ability to act','give it unlimited flexibility','celebrate its achievements','s2 作动词表示限制。'),Q('fetter',3,3,'A lack of data can be a fetter on a project because it?','holds back progress','guarantees quick decisions','makes every result certain','s3 比喻指阻碍。'),Q('fetter',4,2,'Which sentence uses fetter as a verb?','The rigid rule fetters the team’s response.','The guard counted each iron chain.','The celebration had a festive mood.','fetter 作动词表示束缚或限制。')]);
P('fetus','Fetus 源自拉丁语 fetus“怀孕、孕育、后代”，指胚胎发育到一定阶段后的未出生胎儿。',C('fetus.s1','发育与医学','The ultrasound image showed the fetus moving its arms, and the clinician recorded the measurements for the next appointment.','超声图像显示胎儿在活动手臂，临床人员记录了各项测量值以供下次复诊。','The ultrasound image showed the fetus moving its arms / and the clinician recorded the measurements / for the next appointment.','fetus 指尚未出生的后期发育个体；showed 后接宾语和动作补语。','超声观察的是仍在子宫内发育的胎儿。'),M('The report called a newborn baby still inside the uterus a fetus after delivery.','The report called the developing unborn offspring a fetus before delivery.','出生后已经离开子宫的婴儿不再是未出生胎儿。'),[Q('fetus',1,1,'A fetus is?','an unborn offspring at a later stage of development','a seedling growing in soil','a person who has emigrated','fetus 指未出生的发育个体。'),Q('fetus',2,1,'Which tool may show a fetus before birth?','an ultrasound scanner','a soil thermometer','a passport reader','超声可观察子宫内的胎儿。'),Q('fetus',3,1,'Fetus is a term most closely associated with?','pregnancy and prenatal development','public celebrations','family feuds','该词属于妊娠与产前发育语境。'),Q('fetus',4,1,'A fetus differs from a newborn because the fetus?','has not yet been born','has already started school','is a type of plant seed','胎儿尚未出生。')]);
P('feud','Feud 经古法语和日耳曼语中关于争斗或封地的词进入英语；现代可指长期激烈的家族或群体仇怨，也可作动词结仇争斗，历史义则指封地。',[C('feud.s1','家族与争端','The neighboring families ended a decades-long feud after both sides agreed to repair the shared bridge.','两家同意共同修缮桥梁后，邻近家族之间持续数十年的仇怨终于结束。','The neighboring families ended a decades-long feud / after both sides agreed / to repair the shared bridge.','feud 作名词指长期激烈争吵；after 引出结束争端的条件。','延续数十年的家族对立是长期仇怨。'),C('feud.s2','群体冲突','The two departments have feuded over office space for months, although they share the same project goals.','两个部门虽然项目目标相同，却为办公空间争执了数月。','The two departments have feuded over office space / for months / although they share the same project goals.','feud 作动词表示长期争斗；over 引出争执主题。','持续数月的部门对抗体现动词义。'),C('feud.s3','中世纪历史','The historian explained that a medieval lord could grant a feud to a follower in return for service and loyalty.','历史学家解释，中世纪领主可把封地授予追随者，以换取服务和忠诚。','The historian explained / that a medieval lord could grant a feud / to a follower in return for service and loyalty.','feud 的历史义指领主授予的封地；in return for 表示授予的交换条件。','领主以土地换取效忠，体现封地义。')],M('The families ended their feud by renewing their bitter quarrel and refusing to communicate.','The families ended their feud by settling the dispute and cooperating on the bridge.','继续争吵、拒绝沟通并未结束仇怨。'),[Q('feud',1,1,'A family feud is?','a long and bitter quarrel between families','a public outdoor fair','a period of intense enthusiasm','s1 指长期家族仇怨。'),Q('feud',2,2,'Two departments that feud over space?','take part in a prolonged quarrel about it','share it without disagreement','grant it as a medieval fief','s2 作动词指长期争斗。'),Q('feud',3,3,'In a medieval history text, a feud may mean?','land granted by a lord to a follower','an unpaid personal loan','a person’s ability to have children','s3 是历史上的封地义。'),Q('feud',4,1,'Which event could end a feud?','both families settle the dispute and cooperate','both sides restart the same fight','one group refuses all discussion','协商解决并合作有助结束长期争端。')]);
P('feudalism','Feudalism 由 feudal 加 -ism 构成，feudal 与中世纪拉丁语 feudum“封地”相关，指领主、附庸和农奴围绕土地与义务组织的社会制度。',C('feudalism.s1','中世纪社会制度','The class studied feudalism by tracing how land grants connected lords, vassals, and peasants through obligations and service.','课堂通过梳理土地授予如何把领主、附庸和农民与义务、服务联系起来，研究封建制度。','The class studied feudalism / by tracing how land grants connected lords, vassals, and peasants / through obligations and service.','feudalism 指以土地和服务义务组织的社会秩序；by 引出研究方法。','领主、附庸和农奴之间的土地义务是其制度特征。'),M('The historian defined feudalism as a system in which land and service obligations played no role.','The historian defined feudalism as a social order organized around land, lords, vassals, and service.','封建制度以土地及服务义务为核心，不是与之无关。'),[Q('feudalism',1,1,'Feudalism was a social order organized around?','land, lords, vassals, and obligations','modern factories and wage contracts only','elections for public office','封建制度以土地关系和义务为基础。'),Q('feudalism',2,1,'In feudalism, a land grant could connect a lord with?','a follower who owed service or loyalty','a passenger buying a train ticket','a scientist measuring a fetus','领主授地常与附庸的服务义务相连。'),Q('feudalism',3,1,'Which topic belongs in a lesson on feudalism?','how landholding shaped medieval social duties','how fertilizers improve modern crops','how to identify a public official','封建制度是中世纪土地与社会义务体系。'),Q('feudalism',4,1,'The suffix -ism in feudalism helps form a noun for?','a system or social order','a person who emigrates','a small length unit','-ism 常表示体系或制度。')]);
P('feverishly','Feverishly 由 fever 加 -ish 与 -ly 构成，表示以近乎发烧般的急切、狂热能量做事。',C('feverishly.s1','紧急工作','The rescue team worked feverishly through the night to locate the missing hikers before the temperature dropped.','救援队彻夜拼命搜寻失踪徒步者，希望赶在气温下降前找到他们。','The rescue team worked feverishly through the night / to locate the missing hikers / before the temperature dropped.','feverishly 修饰 worked，表示以急切、紧张的能量工作；to 引出工作目标。','彻夜紧急搜寻体现拼命而紧张的行动。'),M('The crew worked feverishly by relaxing all night and making no effort to find the hikers.','The crew worked feverishly by searching urgently through the night.','整夜放松、毫不搜寻与 feverishly 的拼命行动相反。'),[Q('feverishly',1,1,'To work feverishly is to work with?','frantic energy and urgency','slow indifference and no effort','a calm lack of interest','feverishly 表示狂热、拼命地。'),Q('feverishly',2,1,'Why did the rescue team work feverishly?','they urgently searched before conditions worsened','they had no deadline or task','they wanted to avoid all effort','紧急搜救需要高度投入。'),Q('feverishly',3,1,'Which action is done feverishly?','typing urgent reports rapidly through the night','sitting quietly with no task','walking leisurely after work','急切快速地连夜写报告符合该副词。'),Q('feverishly',4,1,'Feverishly is related to which noun?','fever','fete','fetus','feverishly 由 fever 派生。')]);
P('fiance','Fiance 来自法语 fiancé，源自 fiancer“订婚”，指已订婚、将与某人结婚的男性。',C('fiance.s1','关系与婚约','Rosa introduced her fiancé to her cousins at the family dinner, explaining that they planned to marry next spring.','罗莎在家庭晚餐上把未婚夫介绍给表亲，并说两人计划明年春天结婚。','Rosa introduced her fiancé to her cousins / at the family dinner / explaining that they planned to marry next spring.','fiancé 指已订婚的男性伴侣；that 从句说明婚约安排。','计划与罗莎结婚的男性是她的未婚夫。'),M('Rosa called the man her fiancé even though he was her sister’s future husband, not her own partner.','Rosa called her own future husband her fiancé.','fiancé 是说话者本人已订婚的男性伴侣，不是她姐姐的未婚夫。','word-choice'),[Q('fiance',1,1,'A woman’s fiancé is the man who?','is engaged to marry her','is her brother’s newborn child','works as her wedding photographer','fiancé 指女性已订婚的男性伴侣。'),Q('fiance',2,1,'When does someone become a fiancé?','after becoming engaged to be married','after attending a public fete','after moving to another country','订婚后称 fiancé。'),Q('fiance',3,1,'Which sentence uses fiance correctly?','She introduced her fiancé, the man she plans to marry.','She called her unmarried neighbor her fiancé without an engagement.','Her fiancé was the woman who plans to marry her.','该词指已订婚的男性。'),Q('fiance',4,1,'In standard spelling, fiance traditionally refers to?','a man who is engaged to be married','a woman who is engaged to be married','either person’s wedding guest','fiancé 是男性形式，fiancée 是女性形式。')]);
P('fiancee','Fiancee 是法语 fiancée 的去重音符号拼写，与 fiancé 同源，指已订婚、将与某人结婚的女性。',C('fiancee.s1','关系与婚约','Dmitri thanked his fiancée for helping plan the ceremony, and the couple chose a date for the following June.','德米特里感谢未婚妻帮忙筹备仪式，两人选定了次年六月的婚期。','Dmitri thanked his fiancée / for helping plan the ceremony / and the couple chose a date for the following June.','fiancée 指已订婚的女性伴侣；for 引出感谢原因。','与德米特里计划结婚的女性是他的未婚妻。'),M('Dmitri called his male future husband his fiancée, using the feminine form for a man.','Dmitri called his female future wife his fiancée.','fiancée 是女性形式，男性形式为 fiancé。','word-choice'),[Q('fiancee',1,1,'A man’s fiancée is the woman who?','is engaged to marry him','is his future mother-in-law','has already become his wedding guest only','fiancée 指男性已订婚的女性伴侣。'),Q('fiancee',2,1,'Which form conventionally refers to a woman?','fiancee','fiance','fetus','fiancee 对应女性形式。'),Q('fiancee',3,1,'Dmitri thanked his fiancée for planning their wedding. She is?','the woman he is engaged to marry','his unrelated colleague','the person who officiates at every wedding','语境中的 fiancée 是他的未婚妻。'),Q('fiancee',4,1,'Fiancee differs from fiance in traditional gender marking because fiancee refers to?','a woman who is engaged','a man who is engaged','a person who is not engaged','fiancée 是女性形式。')]);
P('fibrous','Fibrous 由 fiber 加 -ous 构成，可形容由细丝或纤维组成的材料，也可指富含膳食纤维的食物。',[C('fibrous.s1','材料与结构','The rope was fibrous, with many thin strands twisted together to make a strong cable.','这根绳索由许多细纤维绞合而成，结构坚韧。','The rope was fibrous / with many thin strands twisted together / to make a strong cable.','fibrous 描述材料由纤维构成；with 短语说明其结构。','多股细丝绞合体现纤维结构。'),C('fibrous.s2','营养与食物','The nutritionist recommended fibrous vegetables such as beans and broccoli to help the patient increase dietary fiber.','营养师建议病人多吃豆类和西兰花等富含纤维的蔬菜，以增加膳食纤维。','The nutritionist recommended fibrous vegetables / such as beans and broccoli / to help the patient increase dietary fiber.','fibrous 描述食物含有较多纤维；such as 举例说明。','这些食物能增加膳食纤维摄入。')],M('The fibrous vegetable contained no dietary fiber and consisted only of clear water.','The fibrous vegetable contained abundant dietary fiber.','完全不含纤维与该语境中的 fibrous 相反。'),[Q('fibrous',1,1,'A fibrous material is made of?','small threads or fibers','a single sheet of liquid','metal without any strands','s1 指由纤维组成。'),Q('fibrous',2,2,'Fibrous vegetables are useful in a diet because they?','contain a lot of dietary fiber','contain no plant material','are made entirely of sugar','s2 指富含膳食纤维。'),Q('fibrous',3,1,'Which object is fibrous in structure?','a cable made of many twisted strands','a smooth glass marble','a single sheet of polished metal','多股绞合绳索具有纤维结构。'),Q('fibrous',4,2,'Which food could be described as fibrous?','broccoli rich in dietary fiber','clear water with no solid material','a spoon made from steel','富含膳食纤维的蔬菜符合该义。')]);
P('fickle','Fickle 来自中古英语词，常用于形容情绪或意见容易无故改变，也可批评在关系中不忠、靠不住的人。',[C('fickle.s1','偏好与变化','The fickle audience cheered the singer one minute and booed the next when the sound system briefly failed.','音响短暂故障时，反复无常的观众前一分钟还为歌手欢呼，下一分钟就开始嘘声。','The fickle audience cheered the singer one minute / and booed the next / when the sound system briefly failed.','fickle 修饰 audience，表示态度易变；one minute… the next 展示变化。','观众情绪迅速转变，体现反复无常。'),C('fickle.s2','忠诚与关系','He proved a fickle friend by abandoning the group whenever another invitation seemed more exciting.','只要出现更吸引人的邀约，他就抛下朋友们，证明自己是个靠不住的朋友。','He proved a fickle friend / by abandoning the group / whenever another invitation seemed more exciting.','fickle 描述关系中不忠、靠不住；by 引出表现方式。','经常为了新邀约抛弃朋友，说明缺乏忠诚。')],M('The fickle voter supported the same candidate consistently for decades and never changed an opinion.','The fickle voter changed support repeatedly without a clear reason.','长期稳定、不改意见不是 fickle。'),[Q('fickle',1,1,'A fickle person often?','changes feelings or opinions without clear reason','keeps every preference unchanged','avoids all decisions because of debt','s1 指态度或意见容易改变。'),Q('fickle',2,2,'A fickle friend may?','abandon a friendship whenever something more appealing appears','remain loyal through ordinary difficulties','help friends keep a promise','s2 可指薄情、不可靠。'),Q('fickle',3,1,'Which audience is fickle?','one that cheers and then boos after a minor change','one that listens quietly throughout','one that leaves before the performance starts','情绪快速改变的观众反复无常。'),Q('fickle',4,2,'Which behavior suggests a fickle friend?','repeatedly dropping plans for a more exciting invitation','keeping a promise despite inconvenience','supporting a friend during a hard week','频繁为了新鲜事抛下朋友说明不可靠。')]);
P('impunity','Impunity 来自拉丁语 impunitas，由 in-“不”与 poena“惩罚”相关部分构成，指做错事却不受惩罚的状态。',C('impunity.s1','法律与问责','The inspector warned that companies must not dump waste with impunity simply because the river is far from the city.','检查员警告，不能因为河流远离城市就让企业倾倒废物而不受惩罚。','The inspector warned / that companies must not dump waste with impunity / simply because the river is far from the city.','with impunity 表示不受惩罚地；must not 否定这种逃避问责的可能。','检查员要求追究污染责任，不让企业逍遥法外。'),M('The company dumped toxic waste with impunity after regulators fined it and required a cleanup.','The company dumped toxic waste but not with impunity, because regulators fined it and required a cleanup.','已经被罚款并被要求清理，说明并非免受惩罚。','grammar'),[Q('impunity',1,1,'To act with impunity is to?','do something wrong without being punished','receive a reward for careful conduct','admit a mistake and repair the harm','impunity 指不受惩罚。'),Q('impunity',2,1,'Why did the inspector reject dumping waste with impunity?','environmental violations should still bring accountability','the river was too far away to exist','companies must never follow any rules','违法排污不能逃避问责。'),Q('impunity',3,1,'Which situation shows impunity?','a rule-breaker repeatedly avoids any penalty','a driver pays a fine for speeding','a company repairs damage after a court order','该词指犯错而未受惩罚。'),Q('impunity',4,1,'The phrase “with impunity” is closest to?','without suffering punishment','with complete permission from a judge','in exchange for a penalty','with impunity 即不受惩罚地。')]);
P('impure','Impure 由 in-“不”与 pure“纯净的”构成，可指混有不需要物质的东西，也可在旧式道德语境中指被认为不洁或不道德的。',[C('impure.s1','科学与样本','The lab rejected the impure water sample because traces of oil had entered the container during collection.','实验室拒收了不纯净的水样，因为采集时有微量油污进入容器。','The lab rejected the impure water sample / because traces of oil / had entered the container during collection.','impure 修饰 sample，表示混有不需要的物质；because 引出污染原因。','油污混入样本，导致水样不纯。'),C('impure.s2','旧式道德用法','In the novel’s old-fashioned moral vocabulary, the character is unfairly labeled impure for choosing a life outside the village’s rules.','小说采用陈旧的道德词汇，把选择不同生活方式的人不公平地称为“不洁”。','In the novel’s old-fashioned moral vocabulary / the character is unfairly labeled impure / for choosing a life outside the village’s rules.','impure 的道德义带有旧式评判色彩；for 引出角色被贴标签的缘由。','该词在此是小说中的道德评判，不作客观事实。','context')],M('The sample was impure because it contained only clean water and no unwanted substance.','The sample was pure because it contained only clean water and no unwanted substance.','没有任何杂质的水样是纯净的。'),[Q('impure',1,1,'An impure liquid contains?','an unwanted substance mixed into it','only the intended pure material','a person’s identity card','s1 指不纯、掺杂。'),Q('impure',2,2,'In an old-fashioned moral context, impure may be a label meaning?','considered morally unclean or wrong','scientifically proven to contain oil','unable to reproduce','s2 是带有旧式评判色彩的道德义。'),Q('impure',3,1,'Why was the water sample impure?','oil had entered it during collection','it contained only the intended clean water','it was stored in a sealed bottle','混入油污使样本不纯。'),Q('impure',4,2,'When interpreting a novel that calls someone impure, a reader should notice?','the word may reflect an old-fashioned moral judgment','the word always gives a neutral laboratory result','the word means a person is in debt','该道德义可能体现陈旧的社会偏见。')]);
P('impurity','Impurity 由 impure 加 -ity 构成，可指材料中少量不需要的杂质，也可指不纯或不洁的状态。',[C('impurity.s1','材料检测','The technician measured the impurity in the metal before deciding whether the batch met the engineering standard.','技师先测量金属中的杂质含量，再判断这批材料是否达到工程标准。','The technician measured the impurity in the metal / before deciding / whether the batch met the engineering standard.','impurity 指材料中的不需要成分；before 标出检测与判断的顺序。','检测杂质决定材料能否达标。'),C('impurity.s2','状态与纯度','The purification process reduced the impurity of the water until it was safe for the laboratory procedure.','净化过程降低了水的不纯程度，直到它适合实验室操作。','The purification process reduced the impurity of the water / until it was safe / for the laboratory procedure.','impurity 也可指不纯的状态；reduced 表示这种状态减轻。','净化降低水中不纯因素。')],M('The impurity in the metal was zero because inspectors found a large amount of unwanted material.','The impurity in the metal was high because inspectors found a large amount of unwanted material.','大量不需要物质意味着杂质含量高，而不是为零。'),[Q('impurity',1,1,'An impurity in a material is?','a small amount of an unwanted substance','the pure material itself','a public celebration','s1 指杂质。'),Q('impurity',2,2,'Purification reduces impurity by?','making a substance less contaminated','adding more unwanted material','turning water into a metal','s2 指不纯的状态。'),Q('impurity',3,1,'Why test metal for impurity?','unwanted substances may affect whether it meets a standard','impurity shows that the metal is a person','the test measures a family feud','杂质会影响材料能否达标。'),Q('impurity',4,1,'The suffix -ity in impurity forms a noun for?','a state or quality','a person who performs an action','a distance unit','-ity 构成状态或性质名词。')]);
P('impute','Impute 来自拉丁语 imputare“归算、计入”，表示把过失、动机或结果归因于某人或某个原因。',C('impute.s1','归因与责任','The audit did not impute the delay to the clerk; it traced the missed deadline to a faulty scheduling system.','审计没有把延误归咎于办事员，而是查明错过期限源于排程系统故障。','The audit did not impute the delay to the clerk / it traced the missed deadline / to a faulty scheduling system.','impute A to B 表示把 A 归因于 B；did not 与后文给出真正原因相呼应。','报告明确把延误原因从办事员转向系统故障。'),M('The review imputed the error to the clerk, meaning it cleared the clerk of responsibility.','The review imputed the error to the clerk, meaning it attributed responsibility to the clerk.','impute to 表示归因于，不是免除责任。','meaning'),[Q('impute',1,1,'To impute a mistake to someone is to?','attribute the mistake to that person','erase every record of the mistake','reward the person for preventing it','impute 表示把过失归于某人。'),Q('impute',2,1,'The report imputed the delay to a system fault. What did it do?','identified the system fault as the cause','claimed the delay had no cause','said the system was in debt','impute to 表示把结果归因于。'),Q('impute',3,1,'Which sentence uses impute correctly?','They imputed the damage to a leaking pipe.','They imputed the report from the desk.','They imputed into the room at noon.','常见搭配是 impute something to a cause。'),Q('impute',4,1,'If blame is imputed to a person, the person is?','treated as responsible for it','automatically declared innocent','praised for someone else’s work','被归咎的人被视为负有责任。')]);
P('in','In 源自古英语 in，可作介词表示位于内部、处于某段时间或某方面，也可作副词表示进入、形容词表示流行。',[C('in.s1','位置与空间','The keys are in the drawer beside the front door, under the folded maps.','钥匙在前门旁边的抽屉里，压在折叠地图下面。','The keys are in the drawer / beside the front door / under the folded maps.','in 作介词表示位于某个空间内部；地点短语说明抽屉位置。','钥匙处在抽屉内部。'),C('in.s2','时间与期限','The package should arrive in three days if the weather does not delay the delivery route.','如果天气没有延误配送路线，包裹应在三天后送达。','The package should arrive in three days / if the weather does not delay the delivery route.','in + 时间段可表示从现在起经过多久；if 引出条件。','三天后送达是从当前时间起计算的期限。'),C('in.s3','方向与移动','When the bell rang, the children ran in from the playground to escape the sudden rain.','铃声响起时，孩子们从操场跑进屋里躲避突来的雨。','When the bell rang / the children ran in from the playground / to escape the sudden rain.','in 作副词表示向内、进入；from 标出移动起点。','孩子们跑进建筑物内部。'),C('in.s4','领域与方面','The report found a small improvement in accuracy after the team calibrated the instrument.','报告发现团队校准仪器后，准确度方面有小幅提升。','The report found a small improvement in accuracy / after the team calibrated the instrument.','in 作介词引出改进涉及的方面；after 表示校准后的变化。','in accuracy 表示在准确度方面。'),C('in.s5','流行与时尚','Plain canvas shoes are in this season, and several shops have placed them in their front windows.','本季帆布鞋很流行，几家商店把它们摆在橱窗里。','Plain canvas shoes are in this season / and several shops / have placed them in their front windows.','in 作形容词，口语中表示流行；this season 限定流行时间。','商店展示它们且说本季流行，体现时髦义。')],M('The keys are in the drawer, meaning they are several meters outside it on the floor.','The keys are in the drawer, meaning they are inside it.','in 表示在内部，不是位于容器之外。'),[Q('in',1,1,'If the keys are in a drawer, they are?','inside the drawer','on the roof above the house','outside the drawer in the street','s1 表示内部位置。'),Q('in',2,2,'The train arrives in ten minutes. When is it expected?','ten minutes from now','ten minutes before it departed yesterday','only if the station closes','s2 表示从现在起经过一段时间。'),Q('in',3,3,'When children run in from the rain, in means?','into a building or enclosed place','during a past decade','popular with shoppers','s3 作副词表示进入。'),Q('in',4,5,'If a style is in this season, it is?','fashionable or popular now','inside a drawer','unwell','s5 表示时髦、流行。')]);
P('in addition','In addition 是表示补充的固定短语，意为“此外、另外”，引入额外的信息或项目。',C('in addition.s1','补充信息','The course includes weekly labs; in addition, students receive access to recorded demonstrations.','课程包含每周实验；此外，学生还可以观看录制的演示。','The course includes weekly labs / in addition / students receive access to recorded demonstrations.','in addition 作连接性副词，补充一项额外内容；分号连接相关信息。','录制演示是课程实验之外增加的内容。'),M('The course offers weekly labs; in addition, it offers no other support, so “in addition” means “instead.”','The course offers weekly labs; in addition, students also receive recorded demonstrations.','in addition 表示添加信息，不表示取代前项。'),[Q('in addition',1,1,'In addition means?','also or as an extra','instead of the previous item','because the previous item failed','该短语表示此外、另外。'),Q('in addition',2,1,'Why are recorded demonstrations introduced with in addition?','they are an extra benefit besides weekly labs','they replace the weekly labs','they explain why the course has ended','该短语补充额外课程资源。'),Q('in addition',3,1,'Which sentence uses in addition correctly?','The library has study rooms; in addition, it lends laptops.','In addition the laptop, she walked outside.','The library closed in addition yesterday means it reopened.','in addition 可引出另外提供的服务。'),Q('in addition',4,1,'A speaker who says “In addition, we need a translator” is?','adding another requirement','replacing the earlier requirement','denying that any requirement exists','短语表示增加一项要求。')]);
P('in advance','In advance 是表示时间的固定短语，意为提前、在预定时间之前。',C('in advance.s1','预约与安排','Guests must reserve a table in advance because the small restaurant has only six seats.','客人必须提前订位，因为这家小餐馆只有六个座位。','Guests must reserve a table in advance / because the small restaurant / has only six seats.','in advance 修饰 reserve，表示预先安排；because 引出提前预约的原因。','座位有限，因此要提前预订。'),M('Guests reserved their table in advance after dinner had ended and the restaurant had closed.','Guests reserved their table in advance before arriving for dinner.','用餐结束、餐厅关门后才预订不是提前。'),[Q('in advance',1,1,'To book in advance is to book?','before the time you plan to use something','after the event has ended','only when someone else cancels','in advance 表示提前。'),Q('in advance',2,1,'Why reserve a table in advance at a tiny restaurant?','there may be few seats available','the restaurant has no tables','the meal has already been eaten','座位有限时提前预订更稳妥。'),Q('in advance',3,1,'Which action is done in advance?','buying a ticket a week before the concert','buying a ticket after the concert','asking for a refund after entry','预先购票是在活动前完成。'),Q('in advance',4,1,'“Please notify us in advance” asks someone to notify us?','ahead of time','only after the deadline','instead of notifying anyone','该表达要求提前通知。')]);
P('in case','In case 是表示预防或条件的连词短语，意为“以防、万一”，引出可能发生并需预先准备的情况。',C('in case.s1','准备与预防','Take a printed map in case your phone battery dies while you are hiking beyond the village.','带一份纸质地图，以防你在村外徒步时手机没电。','Take a printed map / in case your phone battery dies / while you are hiking beyond the village.','in case 引出需提前防备的可能情况；while 从句限定可能发生的时间。','纸质地图是为手机可能没电预作准备。'),M('Take a printed map in case your phone battery dies, meaning you should wait until the battery has died before packing one.','Take a printed map in case your phone battery dies, so you are prepared if it happens.','in case 提醒预先准备，而不是等风险发生后才行动。'),[Q('in case',1,1,'Take a flashlight in case the power fails means?','bring it beforehand in case the power goes out','wait until the power fails before finding one','leave it behind because power never fails','in case 表示以防某事发生。'),Q('in case',2,1,'Why carry a printed map in case a phone battery dies?','the map is a backup for a possible problem','the map makes the phone battery charge faster','the battery has already been replaced','纸质地图可以应对手机没电。'),Q('in case',3,1,'Which sentence uses in case to show preparation?','I saved a copy in case the computer crashed.','I saved a copy in case the computer was fixed yesterday.','I deleted the copy in case I needed it later.','提前备份是为防电脑故障。'),Q('in case',4,1,'In case introduces a situation that?','might happen and is worth preparing for','has definitely already happened','is impossible by definition','该短语引出可能发生的情况。')]);
P('in charge','In charge 是形容词短语，表示负责管理某人、某事或某项工作的。',C('in charge.s1','职责与管理','Dr. Malik is in charge of the laboratory schedule and approves every change to the shared equipment calendar.','马利克博士负责实验室排程，并批准共享设备日历上的每项变更。','Dr. Malik is in charge of the laboratory schedule / and approves every change / to the shared equipment calendar.','be in charge of 表示负责；and 连接其管理职责。','他审批排程变更，说明他承担管理责任。'),M('Dr. Malik is in charge of the schedule, meaning he has no responsibility for managing it.','Dr. Malik is in charge of the schedule, meaning he is responsible for managing it.','in charge of 明确表示负责管理。','meaning'),[Q('in charge',1,1,'A person in charge of a project is?','responsible for directing or managing it','in debt to the project','unaware that the project exists','in charge 表示负责。'),Q('in charge',2,1,'Who is in charge of the laboratory schedule?','the person who approves calendar changes','any visitor who enters the lab','a person who has no assigned role','审批安排的人负责管理排程。'),Q('in charge',3,1,'Which sentence uses in charge correctly?','Amira is in charge of the evening shift.','Amira is in charge the evening shift of.','Amira is in charge for the evening shift.','固定搭配是 in charge of。'),Q('in charge',4,1,'If you are in charge, you are expected to?','take responsibility for decisions in that area','avoid every decision and responsibility','leave the country permanently','负责者要承担相应决策责任。')]);
P('in debt','In debt 是形容词短语，表示欠着钱、处于负债状态。',C('in debt.s1','财务与偿还','After paying for the repairs with a loan, the small bakery was in debt and created a monthly repayment plan.','小面包店用贷款支付维修费后陷入负债，于是制定了每月还款计划。','After paying for the repairs with a loan / the small bakery was in debt / and created a monthly repayment plan.','be in debt 表示欠款；and 引出偿债安排。','贷款尚未偿还，因此店铺处于负债状态。'),M('The bakery was in debt because it had repaid every loan and owed no money to anyone.','The bakery was out of debt because it had repaid every loan and owed no money to anyone.','已还清贷款且不欠钱应说 out of debt。','collocation'),[Q('in debt',1,1,'A person in debt?','owes money','has no financial obligations','is responsible for a laboratory','in debt 表示负债。'),Q('in debt',2,1,'Why did the bakery create a repayment plan?','it still owed money from a loan','it had no bills or loans','it was preparing a public fete','尚欠贷款需要安排偿还。'),Q('in debt',3,1,'Which phrase describes someone who owes money?','in debt','in force','in total','in debt 是欠钱。'),Q('in debt',4,1,'If a borrower repays all loans, the borrower is?','out of debt','in debt','in charge','还清欠款后就不再负债。')]);
P('in exchange','In exchange 是表示交换关系的固定短语，意为“作为交换”，说明给出一物或服务以换取另一项。',C('in exchange.s1','交易与互换','The museum lent its photographs to the archive in exchange for access to the archive’s newly catalogued letters.','博物馆把照片借给档案馆，作为交换，它获得了查阅档案馆新编目书信的机会。','The museum lent its photographs to the archive / in exchange for access / to the newly catalogued letters.','in exchange for 后接换取的东西；句中说明双方互惠安排。','照片借展换取书信查阅权，体现交换关系。'),M('The museum lent photographs in exchange for nothing, even though the agreement says it received access to the archive.','The museum lent photographs in exchange for access to the archive.','协议明确写有换取的回报，不能说什么也没换到。'),[Q('in exchange',1,1,'To give something in exchange is to give it?','as part of a trade or reciprocal arrangement','without receiving anything under any arrangement','only after an event has ended','in exchange 表示作为交换。'),Q('in exchange',2,1,'The museum lent photographs in exchange for access. What was the arrangement?','it lent one resource to receive another','it sold both collections permanently','it refused to cooperate','借出照片换取访问权限。'),Q('in exchange',3,1,'Which phrase is normally followed by the thing received?','in exchange for','in debt with','in total of','搭配是 in exchange for something。'),Q('in exchange',4,1,'A student helps a neighbor in exchange for tutoring. The student helps?','to receive tutoring as the return','without any possible reciprocal benefit','because tutoring has already ended','短语说明互相提供的回报。')]);
P('in fact','In fact 是表示补充或纠正的副词短语，意为“事实上、实际上”，引出真实情况或加强前述信息。',C('in fact.s1','事实与澄清','The trail looked difficult on the map; in fact, the first mile was a gentle path through the valley.','地图上这条步道看起来很难；事实上，头一英里只是穿过山谷的缓坡小径。','The trail looked difficult on the map / in fact / the first mile was a gentle path through the valley.','in fact 引出实际情况，对地图留下的印象作补充澄清。','实际路况比地图显示的容易。'),M('The route was easy in fact, meaning that it was actually impossible to complete.','The route was easy in fact, meaning that it was actually possible and gentle.','in fact 强调事实，不会把 easy 解释成 impossible。','meaning'),[Q('in fact',1,1,'In fact means?','really or actually','instead of the previous thing','before the planned time','该短语表示事实上。'),Q('in fact',2,1,'Why say “in fact” about the trail?','to clarify what the real route was like','to exchange one map for another','to say the route is legally active','in fact 引出实际情况。'),Q('in fact',3,1,'Which sentence uses in fact naturally?','The forecast sounded severe; in fact, the day stayed sunny.','In fact the chair, she sat quietly.','The rule is in fact means it is not active.','这里用 in fact 澄清预报与实际天气的差别。'),Q('in fact',4,1,'A speaker says “I am not angry; in fact, I am relieved.” The phrase introduces?','a truthful clarification or added point','a purpose for leaving','a debt that must be paid','该短语用来补充、澄清真实情况。')]);
P('in force','In force 是形容词短语，表示法律、规定或协议目前有效并正在实施。',C('in force.s1','法律与规定','The new parking rule is in force as of Monday, so drivers must now use the marked spaces.','新的停车规定自周一起生效，因此司机现在必须使用划线车位。','The new parking rule is in force as of Monday / so drivers must now use the marked spaces.','in force 表示规则已经有效；so 引出实施后的要求。','规则生效后司机需遵守。'),M('The parking rule is in force although it was repealed last year and is no longer applied.','The parking rule is no longer in force because it was repealed last year.','已废止且不再执行的规定不再生效。','grammar'),[Q('in force',1,1,'A rule that is in force is?','active and currently applied','repealed and no longer valid','a proposal that nobody has adopted','in force 表示生效中。'),Q('in force',2,1,'Why must drivers follow the new parking rule?','it has come into force','it is only a forgotten proposal','it applies only to an old photograph','规定生效后必须遵守。'),Q('in force',3,1,'Which document is likely to be in force?','a current regulation that has taken effect','a law canceled several years ago','a draft still awaiting approval','已经实施的现行规定有效。'),Q('in force',4,1,'“The agreement remains in force” means it?','continues to be legally or officially active','has been canceled','is only being discussed','remains in force 表示仍有效。')]);
P('in order to','In order to 是表示目的的不定式短语，意为“为了”，后接动词原形说明行动目标。',C('in order to.s1','目的与行动','The volunteers labeled every box in order to find the medical supplies quickly during an emergency.','志愿者给每个箱子贴上标签，以便紧急情况下快速找到医疗用品。','The volunteers labeled every box / in order to find the medical supplies quickly / during an emergency.','in order to 后接动词原形，说明贴标签的目的。','标签让医疗用品能在紧急时迅速找到。'),M('The volunteers labeled the boxes in order to finding the supplies quickly.','The volunteers labeled the boxes in order to find the supplies quickly.','in order to 后接动词原形 find，不接动名词 finding。','grammar'),[Q('in order to',1,1,'In order to introduces?','the purpose of an action','a comparison between two objects','a condition that has already failed','该短语引出行动目的。'),Q('in order to',2,1,'In “She called in order to confirm the time,” why did she call?','to confirm the time','because the time was a distance unit','in place of the meeting itself','in order to 说明打电话的目的。'),Q('in order to',3,1,'Which form follows in order to?','the base form of a verb','a noun in the plural only','a verb with -ing in every case','in order to 后接动词原形。'),Q('in order to',4,1,'Which sentence is correct?','We left early in order to catch the first bus.','We left early in order to catching the first bus.','We left early in order catching the first bus.','正确结构为 in order to catch。')]);
P('in part','In part 是表示程度的副词短语，意为“部分地、在一定程度上”，说明原因或结果并非全部。',C('in part.s1','原因与解释','The delay was in part caused by heavy rain, though a late equipment delivery also contributed.','延误部分是由暴雨造成的，不过设备迟到也有影响。','The delay was in part caused by heavy rain / though a late equipment delivery / also contributed.','in part 表示原因只占一部分；though 引出另一项原因。','暴雨是部分原因，设备迟到也有作用。'),M('The report said rain caused the delay in part, meaning rain was the only possible cause.','The report said rain caused the delay in part, while other factors also contributed.','in part 表示部分原因，并非唯一原因。','meaning'),[Q('in part',1,1,'If something is true in part, it is true?','to some extent, but not necessarily completely','only in a different place','because it has been exchanged','in part 表示部分地。'),Q('in part',2,1,'The delay was in part caused by rain. What does that mean?','rain was one contributing cause','rain was certainly the only cause','rain prevented any delay','in part 暗示还有其他因素。'),Q('in part',3,1,'Which sentence uses in part correctly?','The success came in part from careful planning.','The success came in part of a building.','The success came in part to replace planning.','该短语表示成功部分得益于计划。'),Q('in part',4,1,'A result caused in part by cost increases?','has cost increases as one of its causes','has no connection to costs','is fully explained by one unrelated event','该短语限定原因只占一部分。')]);
P('in place of','In place of 是介词短语，意为“代替、取代”，后接被替代的人或事物。',C('in place of.s1','替换与选择','The clinic used a video consultation in place of an in-person visit when the patient could not travel.','病人无法出行时，诊所用视频问诊代替了面诊。','The clinic used a video consultation / in place of an in-person visit / when the patient could not travel.','in place of 后接被取代的事物；when 引出选择替代方式的条件。','视频问诊承担了原本由面诊完成的服务。'),M('The clinic used a video visit in place of replacing it with another visit, so it did not replace anything.','The clinic used a video visit in place of an in-person appointment.','in place of 表示取代原有方式。','meaning'),[Q('in place of',1,1,'To use A in place of B is to use A?','instead of B','after B has already been used twice','because B is a location','in place of 意为代替。'),Q('in place of',2,1,'Why did the clinic use video in place of a visit?','the patient could not travel for an in-person appointment','the patient had already arrived at the clinic','video calls cannot connect people','视频服务替代了无法进行的面诊。'),Q('in place of',3,1,'Which phrase has the same meaning as in place of?','instead of','in addition to','in advance of','in place of 表示 instead of。'),Q('in place of',4,1,'Which sentence uses the phrase correctly?','They served tea in place of coffee.','They served in place of tea coffee.','They served tea in place coffee of.','短语后接被替代的事物。')]);
P('in spite of','In spite of 是表示让步的介词短语，意为“尽管、不顾”，后接名词、代词或动名词。',C('in spite of.s1','让步与结果','In spite of the strong wind, the ferry reached the island safely before sunset.','尽管风很大，渡船还是在日落前安全抵达岛上。','In spite of the strong wind / the ferry reached the island safely / before sunset.','in spite of 引出与主句结果形成反差的情况；后接名词短语 the strong wind。','风大没有阻止渡船安全抵达。'),M('In spite of the road was flooded, the bus continued on its route.','In spite of the flooded road, the bus continued on its route.','in spite of 后接名词短语，不能直接接完整句子。','grammar'),[Q('in spite of',1,1,'In spite of means?','despite or even though something is true','because something is true','instead of something else','in spite of 表示尽管。'),Q('in spite of',2,1,'The ferry arrived in spite of strong winds. What happened?','it arrived despite the difficult weather','it arrived only because there was no wind','it replaced the wind','风大但仍抵达，体现让步。'),Q('in spite of',3,1,'What can follow in spite of?','a noun phrase or an -ing form','a full clause with a subject and finite verb directly','only a question mark','该介词短语后接名词短语或动名词。'),Q('in spite of',4,1,'Which sentence is grammatically correct?','In spite of feeling tired, Mei finished the report.','In spite of Mei felt tired, she finished the report.','In spite feeling tired of, Mei finished the report.','in spite of 后可接动名词 feeling。')]);
P('in the end','In the end 是表示结果的副词短语，意为“最后、到头来”，强调经历一段过程后的最终结局。',C('in the end.s1','决定与结局','The committee considered three locations and, in the end, chose the site beside the railway station.','委员会考察了三个地点，最后选择了火车站旁的场地。','The committee considered three locations / and, in the end, chose the site / beside the railway station.','in the end 表示经过考虑后的最终决定；and 连接过程与结局。','委员会比较多个地点后才作出最终选择。'),M('The committee chose the site in the end before it began considering any locations.','The committee considered the locations first and chose the site in the end.','in the end 指过程之后的最终结果。','grammar'),[Q('in the end',1,1,'In the end refers to?','the final result after a process','the first step before anything begins','a temporary exchange between people','in the end 表示最后结果。'),Q('in the end',2,1,'The committee visited three sites and in the end chose one. When did it decide?','after considering the options','before visiting any site','only during the first visit','最终决定是在比较之后作出的。'),Q('in the end',3,1,'Which sentence uses in the end naturally?','In the end, they took the train after comparing routes.','In the end means they had not yet begun.','They used in the end of to mean beside the station.','该短语引出比较之后的结果。'),Q('in the end',4,1,'In the end is closest to?','finally or ultimately','in total','in advance','in the end 指最后、最终。')]);
P('in the interim','In the interim 是较正式的时间短语，意为“在此期间”，指两个事件、阶段或决定之间的过渡时间。',C('in the interim.s1','等待与过渡','The new director will start in July; in the interim, the deputy will approve urgent requests.','新主任将在七月上任；在此期间，副主任将审批紧急申请。','The new director will start in July / in the interim / the deputy will approve urgent requests.','in the interim 指正式任命前的过渡时段；分号连接先后安排。','副主任在两任期之间暂时负责。'),M('The deputy approved requests in the interim after the new director had already served for several years.','The deputy approved requests in the interim before the new director began work.','新主任已经工作多年就不是两者之间的过渡期。'),[Q('in the interim',1,1,'In the interim means?','during the time between two events or stages','after everything has permanently ended','in place of every other option','该短语指在此期间。'),Q('in the interim',2,1,'Who handles urgent requests in the interim?','the deputy, while the new director has not yet started','the retired director forever','no one, because the office is closed','副主任在新主任上任前暂时负责。'),Q('in the interim',3,1,'Which period is an interim?','the weeks between one manager leaving and another starting','the entire career of one manager','a moment after a meeting has ended','两任管理者之间的时间是过渡期。'),Q('in the interim',4,1,'In the interim is similar to?','meanwhile','in total','in debt','该短语接近 meanwhile。')]);
P('in total','In total 是表示合计结果的副词短语，意为“总共、总计”，把多个部分相加后给出整体数量。',C('in total.s1','统计与合计','The volunteers collected 186 blankets in total, including donations from three nearby schools.','志愿者总共收集了186条毯子，其中包括附近三所学校的捐赠。','The volunteers collected 186 blankets in total / including donations / from three nearby schools.','in total 表示把所有来源合并后的总数；including 补充其中一部分。','186 是将各处捐赠加总后的数量。'),M('The schools donated 186 blankets in total, but the recorded overall total was only 40.','The schools donated 40 blankets in total, with 186 belonging to a separate earlier count.','总数应与加总后的数据一致，不能同时为186与40。','measurement'),[Q('in total',1,1,'In total means?','when all parts are added together','before the first part is counted','in exchange for another amount','in total 表示合计。'),Q('in total',2,1,'If three schools donate blankets and the report gives one combined number, that number is?','the amount in total','the amount in advance','the amount in place of the schools','合并三所学校捐赠量后得到总数。'),Q('in total',3,1,'Which sentence uses in total correctly?','The three boxes held 48 books in total.','The three boxes held in total of 48 books.','The total books were in total to the boxes.','常用结构为数量 + in total。'),Q('in total',4,1,'A survey reports 12 votes for one option and 8 for another. The votes in total are?','20','4','12','12 加 8 的总数是20。')]);
P('in what place','In what place 是用于询问地点的疑问短语，意思相当于 where，即“在什么地方”。',C('in what place.s1','地点询问','The form asks in what place the witness first saw the missing bicycle, so the investigator can map the route.','表格询问证人最初在什么地方看见失窃自行车，以便调查人员绘制路线图。','The form asks in what place the witness first saw the missing bicycle / so the investigator can map the route.','in what place 是地点疑问短语，询问事件发生在哪里；so 引出提问目的。','问题要求证人指出第一次看见自行车的地点。'),M('The form asks in what place the witness saw the bicycle, and expects an answer naming the time of day.','The form asks in what place the witness saw the bicycle, and expects an answer naming a location.','in what place 问的是地点，不是时间。','meaning'),[Q('in what place',1,1,'In what place asks about?','where something happened','when it happened','why it happened','该疑问短语询问地点。'),Q('in what place',2,1,'A witness asked in what place the bicycle was seen should name?','a location','a date','a reason','问题中的 place 指地点。'),Q('in what place',3,1,'Which question is closest in meaning to “in what place”?','Where did you first see it?','When did you first see it?','How did you first see it?','where 与 in what place 意思相近。'),Q('in what place',4,1,'Why ask in what place a sighting occurred?','to identify the location','to calculate the witness’s age','to learn what the witness ate','该短语用于查明事件位置。')]);
P('in what way','In what way 是询问方式、方法或方面的疑问短语，意思相当于 how。',C('in what way.s1','方式与方法','The survey asks in what way the new bus route has changed residents’ commutes, inviting them to describe specific effects.','问卷询问新公交线路以什么方式改变了居民的通勤，邀请他们说明具体影响。','The survey asks in what way the new bus route has changed residents’ commutes / inviting them / to describe specific effects.','in what way 询问改变的方式或方面；inviting 补充问卷希望得到的回答。','问卷让居民描述线路产生的具体影响。'),M('The survey asks in what way the route changed commutes, but respondents are instructed to provide only a street address.','The survey asks in what way the route changed commutes, so respondents should describe the manner or effect.','in what way 问方式或影响，不是单独询问地址。','meaning'),[Q('in what way',1,1,'In what way asks?','how or by what manner','where something is located','who owns a vehicle','该短语相当于 how。'),Q('in what way',2,1,'If residents are asked in what way a route changed their commute, they should describe?','the manner or effect of the change','the exact place where they live only','the date the road was built','问题询问变化的方式或影响。'),Q('in what way',3,1,'Which question is closest to “In what way did it help?”','How did it help?','Where did it help?','When did it help?','in what way 对应 how。'),Q('in what way',4,1,'A form asks in what way a service could improve. It requests?','suggestions about how it could improve','the user’s home address','the year the service began','该问句询问改进方法。')]);
P('in which','In which 是介词 in 与疑问或关系代词 which 的组合，可表示“在其中”，指出某事发生于前文提到的地方或情境。',C('in which.s1','关系从句与地点','They restored the room in which the town’s first council meeting was held, preserving its original wooden table.','他们修复了镇上首次议会会议举行的房间，并保留了原来的木桌。','They restored the room / in which the town’s first council meeting was held / preserving its original wooden table.','in which 引导关系从句，指会议发生在该房间里；which 回指 room。','房间是会议举行的地点。'),M('They restored the room in which the meeting was held, meaning the meeting took place outside that room.','They restored the room in which the meeting was held, meaning the meeting took place inside it.','in which 在此指事件发生在房间之中。'),[Q('in which',1,1,'In “the room in which we met,” in which means?','inside or within that room','because of that room','after that room was sold','in which 表示在该处。'),Q('in which',2,1,'The clause “in which the meeting was held” tells us?','where the meeting took place','who chaired the meeting','how long the meeting lasted','in which 从句说明会议地点。'),Q('in which',3,1,'Which phrase is equivalent to “the box in which it was stored”?','the box where it was stored','the box when it was stored','the box why it was stored','where 可替换此处关系结构。'),Q('in which',4,1,'In a relative clause, which usually refers back to?','a previously mentioned thing or place','a future event only','an unrelated person','which 回指前文名词。')]);
P('in-between','In-between 由 in 与 between 组合而成，作形容词表示位于两端之间、居于中间的。',C('in-between.s1','位置与阶段','The in-between seat is narrow, but it gives the child a clear view between the two adults.','中间的座位比较窄，不过孩子坐在那里可以清楚地看见两位大人之间的景象。','The in-between seat is narrow / but it gives the child a clear view / between the two adults.','in-between 作形容词修饰 seat，表示处于两者之间；but 引出其优点。','座位位于两名成人中间。'),M('The in-between chair stood at the far end of the row, beyond every other seat.','The in-between chair stood between the two adults.','位于队列最远端的椅子不是中间位置。'),[Q('in-between',1,1,'An in-between position is?','somewhere between two ends or things','at the extreme edge beyond both','the final result after a long process','in-between 表示中间的。'),Q('in-between',2,1,'Which seat is in-between?','the chair placed between two other chairs','the chair at the end of the row','a chair stored in another building','处在两把椅子之间的位置符合含义。'),Q('in-between',3,1,'In-between can describe?','a middle stage separating two stages','a completed final decision','a person who owes money','该词指两端之间的状态或阶段。'),Q('in-between',4,1,'The prefix in- and word between together describe?','a position located between things','a position inside a single object','a position after everything ends','in-between 描述处在两者之间。')]);
P('in-depth','In-depth 由 in 与 depth 组合，作形容词表示对主题进行仔细、全面而详细的研究或说明。',C('in-depth.s1','研究与分析','The newspaper published an in-depth investigation of the water supply, tracing the contamination from the source to nearby homes.','报纸刊登了对供水情况的深入调查，追踪污染从源头到附近住户的传播。','The newspaper published an in-depth investigation of the water supply / tracing the contamination / from the source to nearby homes.','in-depth 修饰 investigation，强调调查细致全面；tracing 补充调查内容。','调查追踪完整路径，显示分析深入。'),M('The newspaper called its one-line, unverified note an in-depth investigation of the entire water system.','The newspaper called its carefully researched, detailed report an in-depth investigation.','一句未经核实的简短说明并非全面深入调查。'),[Q('in-depth',1,1,'An in-depth report is?','careful and detailed','brief and unsupported','only about the middle of a room','in-depth 表示深入、彻底。'),Q('in-depth',2,1,'Why was the water investigation in-depth?','it traced the problem from its source to affected homes','it mentioned the water in one unverified line','it avoided examining the cause','追查源头和影响范围体现深入调查。'),Q('in-depth',3,1,'Which task needs an in-depth analysis?','examining evidence and causes in detail','glancing at a title for one second','counting one item without context','全面分析需要详细考察。'),Q('in-depth',4,1,'In-depth is used before a noun as?','a compound adjective','a plural noun','a past-tense verb','in-depth 通常作复合形容词。')]);
P('inability','Inability 由 in- 与 ability 组成，指缺少完成某项具体行动或任务的能力。',C('inability.s1','能力与支持','Her inability to lift the heavy crate safely led the team to use a small mechanical hoist.','她无法安全抬起沉重箱子，因此团队改用小型机械吊具。','Her inability to lift the heavy crate safely / led the team / to use a small mechanical hoist.','inability to do 表示不能做某事；to use 说明团队采取的应对措施。','无法安全搬运促使团队提供辅助设备。'),M('Her inability to read the label meant she read it perfectly without help.','Her ability to read the label meant she read it without help.','inability 表示缺乏能力，与能独立读懂相反。','word-choice'),[Q('inability',1,1,'An inability to do something is?','a lack of ability to do it','a strong skill in doing it','a promise to do it later','inability 表示无力或不能。'),Q('inability',2,1,'Why did the team use a hoist?','the worker could not safely lift the crate','the crate was already airborne','the worker was in charge of the schedule','吊具弥补了搬箱子的能力限制。'),Q('inability',3,1,'Which phrase correctly follows inability?','inability to concentrate','inability concentrating to','inability of concentrate','常用结构是 inability to do。'),Q('inability',4,1,'Inability is the opposite of?','ability','inactivity','inaccuracy','inability 与 ability 意义相反。')]);
P('inaccessible','Inaccessible 由 in-“不”与 accessible“可接近的”构成，可指难以到达、难以获得或难以理解的。',[C('inaccessible.s1','地形与到达','The mountain clinic becomes inaccessible in winter when snow covers the only road leading through the pass.','冬季积雪覆盖唯一穿越山口的道路后，山中诊所就难以抵达。','The mountain clinic becomes inaccessible in winter / when snow covers the only road / leading through the pass.','inaccessible 描述地点难以到达；when 引出道路被阻断的条件。','唯一道路被雪封住，无法前往诊所。'),C('inaccessible.s2','获取与费用','The rare instrument is inaccessible to most schools because its price is far beyond their annual equipment budget.','这件稀有乐器对大多数学校来说难以获得，因为价格远超年度设备预算。','The rare instrument is inaccessible to most schools / because its price is far beyond / their annual equipment budget.','inaccessible to 可表示难以获得或负担；because 说明原因。','价格过高使学校无法购置。'),C('inaccessible.s3','理解与文本','The article is inaccessible to beginning readers because it assumes extensive knowledge of statistical theory.','这篇文章对初学者来说难以理解，因为它假定读者熟悉统计理论。','The article is inaccessible to beginning readers / because it assumes extensive knowledge / of statistical theory.','inaccessible 可形容作品难懂；because 引出理解困难的原因。','文章预设大量专业知识，初学者难以读懂。')],M('The remote clinic was inaccessible even though a clear paved road reached its entrance all year.','The remote clinic was accessible because a clear paved road reached its entrance all year.','全年畅通的道路使诊所容易到达。'),[Q('inaccessible',1,1,'A clinic becomes inaccessible when?','the route to it is very difficult to reach','every road to it is clear and open','it has many nearby bus stops','s1 指地点难以到达。'),Q('inaccessible',2,2,'An instrument inaccessible to a school may be?','too expensive for the school to obtain','available in every classroom','easy to borrow for free','s2 指难以获得或负担。'),Q('inaccessible',3,3,'An article is inaccessible to beginners if it?','uses ideas they are not equipped to understand','explains every technical term clearly','is written in familiar language','s3 指内容难以理解。'),Q('inaccessible',4,1,'Which is an inaccessible location in winter?','a clinic behind the only snow-blocked pass','a station beside an open paved road','a school on a clear city street','被唯一雪封道路阻断的诊所难以抵达。')]);
P('inaccuracy','Inaccuracy 由 in- 与 accuracy 组成，指信息或测量上的错误，也可指不够准确这一性质。',C('inaccuracy.s1','测量与校对','The editor found an inaccuracy in the chart: the rainfall total was copied from the previous month.','编辑在图表中发现一处错误：降雨总量误抄了上个月的数据。','The editor found an inaccuracy in the chart / the rainfall total was copied / from the previous month.','inaccuracy 可指一个具体错误；冒号引出错误内容。','数值抄错构成信息不准确。'),M('The chart contained an inaccuracy because every rainfall figure matched the verified records exactly.','The chart was accurate because every rainfall figure matched the verified records exactly.','所有数值均与核验记录一致，说明图表准确。','word-choice'),[Q('inaccuracy',1,1,'An inaccuracy in a chart is?','a mistake or lack of precision','a verified fact with no error','an outdoor celebration','inaccuracy 指错误或不精确。'),Q('inaccuracy',2,1,'What was the inaccuracy in the chart?','the rainfall total came from the wrong month','all values matched the records','the chart had a blue border','抄错月份的数值是具体错误。'),Q('inaccuracy',3,1,'Which situation shows inaccuracy?','a report lists 18 when the verified count is 81','a report repeats the verified count 81','a report states that a number is unknown','报告数字与核实结果不符。'),Q('inaccuracy',4,1,'Inaccuracy is the opposite of?','accuracy','inability','inactivity','inaccuracy 与 accuracy 相反。')]);
P('inaccurate','Inaccurate 由 in-“不”与 accurate“准确的”构成，形容陈述、数字或测量结果不正确。',C('inaccurate.s1','数据与事实','The online notice was inaccurate: it listed the library’s holiday hours as nine to five even though the building was closed.','网上通知不准确：它把图书馆假期开放时间写成九点到五点，但图书馆其实关闭。','The online notice was inaccurate / it listed the library’s holiday hours as nine to five / even though the building was closed.','inaccurate 描述信息不正确；冒号后具体说明错误之处。','通知中的开放时间与实际关闭情况矛盾。'),M('The notice was inaccurate because its hours exactly matched the library’s verified schedule.','The notice was accurate because its hours exactly matched the library’s verified schedule.','与核实日程完全一致的信息是准确的。','word-choice'),[Q('inaccurate',1,1,'An inaccurate statement is?','not correct','perfectly exact','too difficult to reach','inaccurate 表示不准确。'),Q('inaccurate',2,1,'Why was the holiday notice inaccurate?','it said the closed library would be open','it correctly listed the closure','it gave the right hours','错误通知把关闭日写成开放。'),Q('inaccurate',3,1,'Which measurement is inaccurate?','a scale reading that differs from a verified weight','a reading that matches the calibration standard','a label correctly identifying a sample','与标准重量不符的读数不准确。'),Q('inaccurate',4,1,'If information is inaccurate, it should be?','corrected using reliable evidence','accepted without checking','replaced with a random guess','不准确信息应依据证据纠正。')]);
P('inactivate','Inactivate 由 in- 与 activate 组成，表示使某物停止工作或使生物活性消失。',C('inactivate.s1','生物实验与处理','Researchers used heat to inactivate the sample’s virus before it was handled in the teaching laboratory.','研究人员在教学实验室处理样本前用加热方式使其中的病毒失去活性。','Researchers used heat to inactivate the sample’s virus / before it was handled / in the teaching laboratory.','inactivate 表示使生物活性停止；to 表示加热的目的。','处理后病毒不再具有活性。'),M('The heating step inactivated the virus, meaning it became more active and began reproducing faster.','The heating step inactivated the virus, meaning it could no longer remain biologically active.','使其活性增加与 inactivate 的含义相反。'),[Q('inactivate',1,1,'To inactivate a virus is to?','stop it from being biologically active','help it reproduce more rapidly','identify its host animal','inactivate 表示使生物失活。'),Q('inactivate',2,1,'Why did researchers heat the sample?','to make the virus inactive before handling','to help the virus spread','to improve the sample’s color','加热用于消除病毒活性。'),Q('inactivate',3,1,'A device can be inactivated when it?','is stopped from functioning','is switched on and operating normally','is measured with a ruler','inactivate 也可指使设备停止工作。'),Q('inactivate',4,1,'Inactivate is the opposite of?','activate','in-depth','inaccurate','前缀 in- 在此表示使之不再 active。')]);
P('inactive','Inactive 由 in- 与 active 组成，形容当前不活动、不运作或没有采取行动的状态。',C('inactive.s1','设备与运行','The backup pump remained inactive while the main pump supplied water, but staff tested the backup each Friday.','主泵供水期间，备用泵一直未运行，不过工作人员每周五都会测试它。','The backup pump remained inactive / while the main pump supplied water / but staff tested the backup each Friday.','inactive 描述设备没有运行；while 表示它处于待用状态的时间。','备用泵当时未工作。'),M('The inactive pump was inactive because it ran continuously at full speed.','The pump was active because it ran continuously at full speed.','持续全速运转表示设备处于 active 状态。','word-choice'),[Q('inactive',1,1,'An inactive device is?','not currently operating','working continuously at full output','too expensive to purchase','inactive 表示不活动或未运行。'),Q('inactive',2,1,'Why was the backup pump inactive?','the main pump was supplying water instead','the backup pump was running at full speed','the water supply had disappeared','备用泵在主泵工作时没有运转。'),Q('inactive',3,1,'Which account might be inactive?','one that has not been used recently','one sending messages every minute','one currently processing a payment','inactive 也可形容没有活动的账户。'),Q('inactive',4,1,'Inactive is formed by adding in- to?','active','accurate','alienable','inactive 与 active 构成反义。')]);
P('inactivity','Inactivity 由 inactive 加 -ity 构成，指不活动、缺少行动或运动的状态。',C('inactivity.s1','健康与日常活动','The health coach encouraged short walks during the workday to reduce inactivity caused by long hours at a desk.','健康教练鼓励人们工作日间隙短暂散步，以减少长时间伏案造成的不活动。','The health coach encouraged short walks / during the workday / to reduce inactivity caused by long hours at a desk.','inactivity 指缺少活动的状态；to reduce 说明散步的目的。','久坐导致身体活动不足。'),M('The exercise program reduced inactivity by asking participants to remain still all day.','The exercise program reduced inactivity by encouraging participants to move regularly.','整天静止会加重不活动，而非减少它。'),[Q('inactivity',1,1,'Inactivity is?','a state of not acting or moving much','continuous energetic movement','a correct measurement','inactivity 表示不活跃状态。'),Q('inactivity',2,1,'Why did the coach suggest short walks?','to reduce long periods of inactivity','to make participants sit longer','to prevent any movement','散步有助减少久坐。'),Q('inactivity',3,1,'Which routine may lead to inactivity?','sitting at a desk for most of the day','walking between meetings','playing a sport after work','长时间坐着不动会导致缺少活动。'),Q('inactivity',4,1,'The suffix -ity turns inactive into a noun for?','a condition or state','a person who performs an action','a specific location','-ity 构成状态名词。')]);
P('inadequacy','Inadequacy 由 in- 与 adequacy 构成，可指数量、质量或能力不足，也可指使某事失败的具体缺陷。',[C('inadequacy.s1','资源与能力','The review found an inadequacy in the emergency plan: it listed shelters but gave no instructions for reaching them.','评估发现应急计划存在不足：它列出了避难所，却没有说明如何抵达。','The review found an inadequacy in the emergency plan / it listed shelters / but gave no instructions for reaching them.','inadequacy 指未达到需要的不足；冒号后具体说明缺陷。','计划缺少路线指引，使其不够充分。'),C('inadequacy.s2','设计缺陷','A loose hinge was the main inadequacy in the cabinet design, allowing the heavy door to sag.','松动的铰链是柜子设计中的主要缺陷，导致沉重的门板下垂。','A loose hinge was the main inadequacy in the cabinet design / allowing the heavy door to sag.','inadequacy 可指导致系统失效的具体缺陷；allowing 补充缺陷造成的后果。','铰链问题使柜门下垂，构成设计缺陷。')],M('The plan’s inadequacy was that it included every necessary route and clear instruction for reaching each shelter.','The plan’s adequacy was that it included every necessary route and clear instruction for reaching each shelter.','内容完整清晰说明计划充分，而非不足。','word-choice'),[Q('inadequacy',1,1,'An inadequacy in a plan is?','a weakness or lack that makes it insufficient','a feature that guarantees success','a festival held outdoors','inadequacy 指不足或缺陷。'),Q('inadequacy',2,2,'A loose hinge that makes a cabinet door sag is?','a specific inadequacy in the design','proof that the design has no flaw','a legal rule in force','具体设计缺陷造成门板下垂。'),Q('inadequacy',3,1,'Which situation shows inadequacy of resources?','a shelter plan lists locations but omits how to reach them','a plan provides routes and transport for everyone','a team has more supplies than it needs','缺少必要路线信息使计划不足。'),Q('inadequacy',4,1,'Inadequacy is related to which adjective?','inadequate','inanimate','inadvertent','inadequate 表示不足的。')]);
P('inadequate','Inadequate 由 in- 与 adequate“足够的”构成，表示数量、质量或能力不足以满足需要。',C('inadequate.s1','供给与需要','The clinic had inadequate storage for the new vaccines, so staff borrowed a temperature-controlled cabinet.','诊所没有足够的空间存放新疫苗，因此工作人员借来一台温控柜。','The clinic had inadequate storage for the new vaccines / so staff borrowed / a temperature-controlled cabinet.','inadequate 修饰 storage，表示未达到需求；so 引出补救措施。','原有储存条件不足以存放疫苗。'),M('The clinic had inadequate storage because every vaccine fit safely in the existing cabinet with room to spare.','The clinic had adequate storage because every vaccine fit safely in the existing cabinet with room to spare.','现有柜子有充足余量，说明储存空间足够。','word-choice'),[Q('inadequate',1,1,'An inadequate supply is?','not enough for the need','more than enough for every use','identical to the requested amount in every case','inadequate 表示不足。'),Q('inadequate',2,1,'Why did the clinic borrow another cabinet?','its existing storage could not hold the vaccines safely','the existing cabinet had plenty of extra space','the vaccines were already discarded','储存空间不足需要补充柜子。'),Q('inadequate',3,1,'Which resource is inadequate for a large class?','ten chairs for thirty students','thirty chairs for thirty students','forty chairs for thirty students','十把椅子无法满足三十名学生的需要。'),Q('inadequate',4,1,'Inadequate is the opposite of?','sufficient','inanimate','in-depth','adequate 表示足够。')]);
P('inadequately','Inadequately 由 inadequate 加 -ly 构成，表示以不足以满足需要的方式。',C('inadequately.s1','施工与保护','The pipes were inadequately insulated, so they froze during the first week of severe cold.','管道保温做得不够，因此在第一周严寒天气里就冻住了。','The pipes were inadequately insulated / so they froze / during the first week of severe cold.','inadequately 修饰 insulated，说明保温程度不足；so 引出后果。','保温不足导致管道结冰。'),M('The pipes were inadequately insulated because a thick protective layer kept them safely above freezing.','The pipes were adequately insulated because a thick protective layer kept them safely above freezing.','厚实保护层使管道安全保温，说明处理充分。','word-choice'),[Q('inadequately',1,1,'If a room is inadequately heated, it is heated?','not enough to meet the need','more than enough for comfort','in place of another room','inadequately 表示不足地。'),Q('inadequately',2,1,'Why did the pipes freeze?','they were not insulated enough','they had a thick protective layer','the weather stayed warm','保温不足导致管道受冻。'),Q('inadequately',3,1,'Which sentence uses inadequately correctly?','The warning signs were inadequately lit at night.','The warning signs were inadequately because lights.','The warning signs inadequately were a location.','副词修饰 lit，说明照明不足。'),Q('inadequately',4,1,'Inadequately is the adverb form of?','inadequate','inactivity','inaccuracy','inadequately 由 inadequate 派生。')]);
P('inadvertent','Inadvertent 源自拉丁语 inadvertens，由 in- 与 advertent“注意的”相关部分组成，形容并非故意、因疏忽发生的。',C('inadvertent.s1','疏忽与后果','An inadvertent click sent the draft to the entire mailing list before the editor had finished checking it.','编辑还没检查完草稿，一次无意的点击就把它发给了整个邮件列表。','An inadvertent click sent the draft / to the entire mailing list / before the editor had finished checking it.','inadvertent 修饰 click，表示非故意；before 引出点击发生的时间。','误点而非故意发送，体现疏忽造成。'),M('The editor made an inadvertent choice after deliberately checking every recipient and confirming the send.','The editor made an inadvertent choice after clicking send by mistake.','仔细核对后有意确认发送，不属于无意疏忽。','word-choice'),[Q('inadvertent',1,1,'An inadvertent action is?','unintentional','carefully planned in advance','legally in force','inadvertent 表示并非故意。'),Q('inadvertent',2,1,'Why was the email sent inadvertently?','the editor clicked send by mistake','the editor checked every address and chose to send','the mailing list was empty','误点发送体现非故意。'),Q('inadvertent',3,1,'Which event is inadvertent?','a person accidentally attaches the wrong file','a person deliberately deletes a file','a person carefully labels a folder','意外附错文件不是有意行为。'),Q('inadvertent',4,1,'Inadvertent is closest in meaning to?','accidental','fervid','in-depth','inadvertent 与 accidental 相近。')]);
P('inadvertently','Inadvertently 由 inadvertent 加 -ly 构成，表示不是有意地、意外地或因疏忽地。',C('inadvertently.s1','意外与信息','Nora inadvertently left the microphone on, and the room heard her private conversation after the meeting.','诺拉不小心忘了关麦克风，会议结束后房间里的人听到了她的私下谈话。','Nora inadvertently left the microphone on / and the room heard her private conversation / after the meeting.','inadvertently 修饰 left，表示不是故意留下麦克风；and 引出意外后果。','她无意中让麦克风保持开启。'),M('Nora inadvertently left the microphone on after checking it was switched off and choosing to record the room.','Nora deliberately left the microphone on after checking it and choosing to record the room.','检查并有意录音说明行为是故意的。','word-choice'),[Q('inadvertently',1,1,'To do something inadvertently is to do it?','by accident rather than by plan','with careful intention','in exchange for a reward','inadvertently 表示意外地。'),Q('inadvertently',2,1,'Why did the room hear Nora’s conversation?','she accidentally left the microphone on','she deliberately announced the conversation','the microphone had no power','忘记关麦克风导致谈话意外被听见。'),Q('inadvertently',3,1,'Which action happened inadvertently?','sending a file to the wrong person by mistake','choosing a recipient after checking the address','turning off a device intentionally','误发文件属于意外行为。'),Q('inadvertently',4,1,'Inadvertently is the adverb form of?','inadvertent','inadequate','inanimate','inadvertently 由 inadvertent 加 -ly 构成。')]);
P('inalienable','Inalienable 由 in- 与 alienable 构成，alienable 与拉丁语 alienare“转让、让与”相关；该词形容不能被转让或剥夺的权利。',C('inalienable.s1','权利与法律','The charter describes access to a fair hearing as an inalienable right that no official may remove arbitrarily.','宪章把获得公平听证的机会称为不可剥夺的权利，任何官员都不得任意取消。','The charter describes access to a fair hearing / as an inalienable right / that no official may remove arbitrarily.','inalienable 修饰 right，表示不可转让或剥夺；that 从句说明权利的保障。','该权利不能被官员任意取消。'),M('The charter called the right inalienable, meaning officials could freely transfer or remove it whenever convenient.','The charter called the right inalienable, meaning officials could not freely transfer or remove it.','inalienable 表示不可转让或剥夺。','meaning'),[Q('inalienable',1,1,'An inalienable right is one that?','cannot be transferred or taken away','must be sold to another person','is only a temporary gift','inalienable 指不可转让、不可剥夺。'),Q('inalienable',2,1,'Why describe a fair hearing as inalienable?','officials should not remove that right arbitrarily','it can be sold to the highest bidder','it exists only during one meeting','该权利不应被任意剥夺。'),Q('inalienable',3,1,'Which item is often called inalienable?','a fundamental human right','a rented chair','an optional coupon','基本权利常称为不可剥夺。'),Q('inalienable',4,1,'The prefix in- in inalienable contributes the sense?','not or opposite of','inside a physical place','very much or intensely','前缀 in- 在此构成否定。')]);
P('inanimate','Inanimate 来自拉丁语 inanimatus，由 in-“无”与 animatus“有生命的”相关部分构成，可指无生命的物体，也可形容缺乏活力的表现。',[C('inanimate.s1','生命与物体','The museum displayed an inanimate clay figure beside photographs of the living dancer who inspired it.','博物馆在启发这尊陶像的舞者照片旁展出了没有生命的陶像。','The museum displayed an inanimate clay figure / beside photographs / of the living dancer who inspired it.','inanimate 描述无生命的物体；beside 对比陶像与真实舞者。','陶像是无生命物件。'),C('inanimate.s2','表达与活力','The actor’s inanimate delivery made the exciting discovery scene sound dull and emotionless.','演员毫无生气的表达让原本激动人心的发现一幕听起来乏味而缺乏情绪。','The actor’s inanimate delivery / made the exciting discovery scene / sound dull and emotionless.','inanimate 可比喻缺乏活力或精神；make 后接宾语和补语。','干巴巴的表达缺少生命力。')],M('The inanimate statue walked across the gallery and spoke to visitors on its own.','The animate performer walked across the gallery and spoke to visitors.','自行行走和说话表现出生命活动，不是无生命雕像。','word-choice'),[Q('inanimate',1,1,'An inanimate object is?','not living','alive and growing','a person who is in charge','s1 指无生命的。'),Q('inanimate',2,2,'An inanimate delivery by an actor sounds?','dull and lacking energy or spirit','highly expressive and lively','inaccurate in its dates only','s2 指表达缺少活力。'),Q('inanimate',3,1,'Which thing is inanimate?','a clay statue','a living dancer','a growing tree','陶像没有生命。'),Q('inanimate',4,2,'Why did the scene sound dull?','the actor delivered it without energy','the actor used lively expression','the scene had no words but strong movement','无活力的表演使场景乏味。')]);
P('inanity','Inanity 来自拉丁语 inanitas“空虚、无内容”，指缺乏意义或判断的状态，也可指愚蠢无聊的话语。',C('inanity.s1','言语与判断','The panel ignored the inanity of the rumor and returned to the documented evidence about the project.','小组没有理会那条毫无意义的谣言，而是回到有关项目的书面证据上。','The panel ignored the inanity of the rumor / and returned / to the documented evidence about the project.','inanity 指缺乏意义或判断的言论；and 连接忽略谣言与回到证据。','谣言空洞无据，因此小组不予理会。'),M('The panel praised the inanity of the detailed evidence because it was clear, logical, and well supported.','The panel rejected the inanity of the rumor because it was empty and unsupported.','清楚、有逻辑且有证据的材料并非 inanities。','word-choice'),[Q('inanity',1,1,'Inanity can mean?','lack of sense or a foolish remark','a carefully reasoned conclusion','a legal rule currently active','inanity 指空洞或愚蠢之言。'),Q('inanity',2,1,'Why did the panel ignore the rumor’s inanity?','it was empty and unsupported','it contained documented evidence','it gave a reliable account of the project','谣言缺乏意义和证据。'),Q('inanity',3,1,'Which comment is an inanity?','a baseless remark that says nothing useful','a concise explanation supported by records','a detailed answer to a relevant question','毫无内容的评论体现 inanity。'),Q('inanity',4,1,'Inanity is related to which adjective?','inane','inaccurate','in-depth','inane 表示愚蠢或空洞的。')]);
P('inappropriate','Inappropriate 由 in- 与 appropriate“合适的”构成，形容不符合某个场合、目的或规范的行为与事物。',C('inappropriate.s1','场合与举止','The guide reminded visitors that loud music was inappropriate inside the quiet memorial hall.','导游提醒游客，在安静的纪念馆内播放大声音乐不合适。','The guide reminded visitors / that loud music was inappropriate / inside the quiet memorial hall.','inappropriate 作表语，表示行为不适合特定场合；that 引出提醒内容。','纪念馆安静肃穆，大声播放音乐不相称。'),M('The guide said loud music was inappropriate for the quiet hall, meaning it was exactly the most suitable choice.','The guide said loud music was appropriate for a lively outdoor concert, not for the quiet hall.','把音乐称为最合适与“不合适”的原句矛盾。','meaning'),[Q('inappropriate',1,1,'An inappropriate action is?','not right or suitable for its setting','perfectly matched to every setting','too difficult to reach','inappropriate 表示不适当。'),Q('inappropriate',2,1,'Why was loud music inappropriate in the memorial hall?','it did not fit the quiet setting','the hall was an outdoor concert venue','the music was never played','场合安静，响亮音乐不相称。'),Q('inappropriate',3,1,'Which choice may be inappropriate at a formal ceremony?','shouting jokes during a moment of silence','following the event’s dress guidance','speaking quietly when invited','在默哀时大声讲笑话不合时宜。'),Q('inappropriate',4,1,'Inappropriate is the opposite of?','appropriate','inanimate','incessant','appropriate 意为合适的。')]);
P('inapt','Inapt 由 in- 与 apt“恰当、能干的”构成，可指言辞不合时宜，也可指某人在某项任务上不熟练。',[C('inapt.s1','措辞与场合','Calling the rescue operation a “game” was an inapt choice of words while families were waiting for news.','家属正在等待消息时，把救援行动称作“游戏”是很不恰当的措辞。','Calling the rescue operation a “game” / was an inapt choice of words / while families were waiting for news.','inapt 修饰 choice of words，表示措辞与场合不匹配；while 交代语境。','严肃救援不应被称为游戏。'),C('inapt.s2','技能与任务','Although she was an inapt swimmer, she trained carefully before joining the beginner’s open-water class.','她虽然游泳不熟练，仍在参加初级公开水域课程前认真训练。','Although she was an inapt swimmer / she trained carefully / before joining the beginner’s open-water class.','inapt 可表示技能不足、不熟练；although 引出与此相对的努力。','她游泳不熟练，因此参加初级课程前先训练。')],M('Calling a tragic rescue operation a game was an inapt choice because it was perfectly sensitive and respectful.','Calling a tragic rescue operation a game was an apt choice only if it were a playful competition.','将严肃救援称为游戏通常不合适。','word-choice'),[Q('inapt',1,1,'An inapt remark is?','unsuitable for the situation','perfectly timed and appropriate','a statement that is unquestionably true','inapt 指不恰当。'),Q('inapt',2,2,'An inapt swimmer is?','not skilled at swimming','an expert swimmer','a person in charge of a pool','s2 指不熟练。'),Q('inapt',3,1,'Which word choice is inapt at a memorial?','calling the tragedy a joke','offering a quiet expression of sympathy','speaking respectfully about the loss','轻佻称呼悲剧不合时宜。'),Q('inapt',4,2,'Which sentence uses the skill sense of inapt?','He was inapt at steering the boat.','Her joke was inapt for the solemn service.','The rule is in force.','“inapt at”可表示某项技能不熟练。')]);
P('inarguably','Inarguably 由 in-、arguable 与 -ly 构成，表示某事清楚到几乎无可争议地。',C('inarguably.s1','证据与结论','The revised bridge is inarguably safer: every load test exceeded the old design’s limits without structural damage.','改造后的桥无可争议地更安全：每次承载测试都超过旧设计的极限，却没有结构损坏。','The revised bridge is inarguably safer / every load test exceeded the old design’s limits / without structural damage.','inarguably 修饰 safer，表示结论明显、难以反驳；冒号后列出证据。','多次测试均通过并超过旧设计指标，支持安全结论。'),M('The bridge was inarguably safer although every test showed cracks and no one could establish its safety.','The bridge’s safety was arguable because the tests showed cracks and left the evidence uncertain.','证据不确定且出现裂纹，不支持“无可争议地更安全”。','meaning'),[Q('inarguably',1,1,'Inarguably means?','so clearly true that it is difficult to dispute','possibly true but not supported','true only in exchange for a reward','inarguably 表示无可争议地。'),Q('inarguably',2,1,'Why was the bridge called inarguably safer?','repeated tests supported the safety claim','every test showed severe damage','no measurements were made','明确通过的测试为结论提供证据。'),Q('inarguably',3,1,'Which claim is inarguably supported?','the verified total is 50 because every counted record sums to 50','the total might be any number because no records exist','the report refuses to show its data','完整核验的数据可支持明确结论。'),Q('inarguably',4,1,'Inarguably is an adverb related to?','arguable','inability','inanimate','该副词由 arguable 派生。')]);
P('inaugural','Inaugural 源自拉丁语 inaugurare“举行就职仪式”，形容某人首次就任的，也形容首次举办的活动。',C('inaugural.s1','任职与首届活动','The mayor’s inaugural address described her priorities for the first year in office.','市长的就职演说阐述了她任期第一年的工作重点。','The mayor’s inaugural address / described her priorities / for the first year in office.','inaugural 修饰 address，表示与首次就任有关；for 短语标明演说涉及的任期。','演说发生在市长开始任职时。','词源与正式就职仪式相关。'),M('The outgoing mayor gave an inaugural speech after serving in office for thirty years.','The newly elected mayor gave an inaugural speech when she first took office.','已任职三十年的卸任市长不是首次就职。','word-choice'),[Q('inaugural',1,1,'An inaugural address is given?','when someone first takes office','after a person has left office permanently','only at an outdoor fair','inaugural 可指就职的。'),Q('inaugural',2,1,'An inaugural festival is likely to be?','the first one of its kind','the final festival ever held','a festival that has no program','inaugural 也表示首次举办的。'),Q('inaugural',3,1,'Which event is inaugural?','the first annual lecture in a new series','the tenth repeat of a long-running event','a private meeting with no opening','首次举行的讲座属于 inaugural。'),Q('inaugural',4,1,'Inaugural is closest in meaning to?','first or opening','in-between','inaccurate','inaugural 表示首届、开创性的。')]);
P('inaugurate','Inaugurate 源自拉丁语 inaugurare，可表示为官员举行就职仪式、开创一项制度，或为建筑举行落成开放仪式。',[C('inaugurate.s1','就职典礼','The council will inaugurate the new chairperson at a public ceremony on Friday.','委员会将在周五的公开仪式上为新主席举行就职典礼。','The council will inaugurate the new chairperson / at a public ceremony / on Friday.','inaugurate 在此表示举行正式就职仪式；at 引出仪式场合。','新主席将在仪式上正式就任。'),C('inaugurate.s2','制度与项目','The university inaugurated a mentoring program that pairs first-year students with experienced tutors.','大学创设了一项导师计划，把一年级学生与有经验的辅导员配对。','The university inaugurated a mentoring program / that pairs first-year students / with experienced tutors.','inaugurate 可表示开创或启动新制度；that 从句说明计划做法。','大学首次启动导师计划。'),C('inaugurate.s3','建筑与开放','The city inaugurated its renovated concert hall with an evening performance by the youth orchestra.','市政府以青年管弦乐团的晚间演出为翻修后的音乐厅举行落成开放仪式。','The city inaugurated its renovated concert hall / with an evening performance / by the youth orchestra.','inaugurate 可指为建筑举行正式开放仪式；with 引出开放活动。','音乐会标志音乐厅正式启用。')],M('The council inaugurated the new chairperson by removing her from office before the ceremony began.','The council inaugurated the new chairperson by formally installing her in office at the ceremony.','就职仪式是正式使人就任，不是解除职务。'),[Q('inaugurate',1,1,'To inaugurate a chairperson is to?','formally install that person in the position','dismiss that person from the position','ask that person to emigrate','s1 指举行就职仪式。'),Q('inaugurate',2,2,'A university inaugurates a mentoring program when it?','starts the new program officially','cancels it before it begins','replaces every student with a tutor','s2 指开创或启动制度。'),Q('inaugurate',3,3,'A city inaugurates a renovated hall by?','officially opening it with a ceremony','closing it permanently without notice','measuring its windows only','s3 指举行建筑落成开放仪式。'),Q('inaugurate',4,2,'Which action can be inaugurated?','a new public service or program','a person’s existing debt','an inaccurate measurement','inaugurate 可表示开创一项新制度。')]);
P('inborn','Inborn 由 in 与 born 组合，形容从出生时就存在的天生特质，也可指构成一个人本性的内在特点。',[C('inborn.s1','先天能力','The study compared an inborn reflex in newborns with movements learned later through practice.','研究比较了新生儿的一种先天反射与后来通过练习学会的动作。','The study compared an inborn reflex in newborns / with movements learned later / through practice.','inborn 修饰 reflex，表示出生时已有；with 对比后天学会的动作。','新生儿反射不是后来练习获得的。'),C('inborn.s2','性格与本性','Her inborn curiosity led her to ask how every household object was designed and made.','她天生的好奇心促使她追问每件家用物品是如何设计和制作的。','Her inborn curiosity / led her to ask / how every household object was designed and made.','inborn 修饰 curiosity，表示内在本性中的特点；how 引出探究内容。','好奇心被描述为她天生的性格特质。')],M('The learned dance routine was inborn because the student had to practice it for several years.','The learned dance routine was acquired through practice, not inborn.','多年练习获得的动作不是出生时就存在的。','word-choice'),[Q('inborn',1,1,'An inborn trait is?','present from birth','learned only after years of training','made inside a machine by design','s1 指先天具有。'),Q('inborn',2,2,'Inborn curiosity describes?','a natural part of someone’s character','a temporary debt','a rule that has just taken effect','s2 指本性中的特质。'),Q('inborn',3,1,'Which ability is most likely inborn?','a newborn reflex present before training','a language learned at school','a skill practiced for several years','出生时已有的反射符合 inborn。'),Q('inborn',4,2,'A person’s inborn curiosity is?','a natural feature of their character','an item built into a house','a quality gained only after a course','inborn 可指本性中的特点。')]);
P('inbuilt','Inbuilt 由 in 与 built 组合，形容按照设计内置在设备、系统或结构之中的。',C('inbuilt.s1','设备与设计','The camera has an inbuilt stabilizer that reduces blur when the photographer takes a picture by hand.','这台相机内置了防抖装置，可减少摄影师手持拍摄时的模糊。','The camera has an inbuilt stabilizer / that reduces blur / when the photographer takes a picture by hand.','inbuilt 修饰 stabilizer，表示它作为设计的一部分装在相机内；that 从句说明功能。','防抖器随相机设计内置。'),M('The camera’s inbuilt stabilizer was a separate accessory that had to be purchased and attached externally.','The camera’s inbuilt stabilizer was already built into the camera by design.','必须另购外接的配件不是内置部件。'),[Q('inbuilt',1,1,'An inbuilt feature is?','built inside as part of the design','stored outside and sold separately','an accidental mistake','inbuilt 表示内建的。'),Q('inbuilt',2,1,'Why is a camera stabilizer inbuilt?','it is already incorporated into the camera','it must be carried as a separate device','it is a person’s natural reflex','inbuilt 表示装置自带。'),Q('inbuilt',3,1,'Which item is inbuilt?','a timer included inside an oven from manufacture','a timer attached later with tape','a paper schedule beside the oven','按设计装在烤箱内部的定时器是内置的。'),Q('inbuilt',4,1,'Inbuilt is closest to?','integrated by design','inaccurate','in debt','inbuilt 指按照设计内置。')]);
P('inca','Inca 是源自克丘亚语 Inka 的名称，指历史上南美洲印加帝国中讲克丘亚语的民族成员。',C('inca.s1','南美历史','The Inca built an extensive road network across the Andes, linking settlements in difficult mountain terrain.','印加人沿安第斯山脉修建了庞大的道路网，把艰险山地中的聚落连接起来。','The Inca built an extensive road network / across the Andes / linking settlements in difficult mountain terrain.','Inca 作名词指印加民族成员；linking 补充说明道路网的作用。','道路网连接安第斯山脉各处聚落。'),M('The Inca were a medieval European dynasty that built castles across the Alps.','The Inca were a Quechua-speaking people whose empire developed in western South America.','印加人属于南美洲历史文明，并非欧洲王朝。','word-choice'),[Q('inca',1,1,'The Inca were a people associated with?','the Andes and western South America','the Alps and medieval Europe','the Nile delta in ancient Egypt','Inca 指南美洲印加民族。'),Q('inca',2,1,'Which achievement is associated with the Inca?','building roads across difficult Andean terrain','inventing the modern railway','founding a community fete in Britain','安第斯山道路网是印加文明成就之一。'),Q('inca',3,1,'The Inca are historically described as?','a Quechua-speaking people','a group of Roman senators','a modern farming tool','印加人讲克丘亚语。'),Q('inca',4,1,'A museum exhibit about an Inca settlement would most likely focus on?','a South American civilization','a European industrial factory','an Arctic snow shelter','Inca 与南美历史相关。')]);
P('incalculable','Incalculable 由 in- 与 calculable 构成，可指数量或价值大到无法计算，也可指结果难以预料。',[C('incalculable.s1','价值与规模','The archive’s records have incalculable value because they preserve voices and events missing from other sources.','档案馆的记录价值难以估量，因为它们保存了其他来源中缺失的人物声音和事件。','The archive’s records have incalculable value / because they preserve voices and events / missing from other sources.','incalculable 修饰 value，表示价值大到无法准确计量；because 说明其重要性。','其他来源无法替代的材料使其价值难以估量。'),C('incalculable.s2','风险与预测','The long-term effects of the chemical spill are incalculable until scientists finish monitoring the river ecosystem.','在科学家完成对河流生态系统的监测之前，这次化学品泄漏的长期影响难以预料。','The long-term effects of the chemical spill are incalculable / until scientists finish monitoring / the river ecosystem.','incalculable 表示后果难以预测；until 限定不确定性持续的时间。','仍需监测生态系统，无法预料长期影响。')],M('The spill’s effects were incalculable because scientists had already measured and predicted every long-term consequence exactly.','The spill’s effects remained uncertain because scientists had not yet measured the long-term consequences.','已经准确预测所有后果，不能说结果难以预料。','meaning'),[Q('incalculable',1,1,'An incalculable value may be?','so great that it cannot be measured precisely','exactly equal to zero','easy to count one by one','s1 指极大到难以计算。'),Q('incalculable',2,2,'The spill’s effects were incalculable because?','their future consequences could not yet be predicted','scientists had already predicted every outcome','the river had never contained water','s2 指难以预料。'),Q('incalculable',3,1,'Which has incalculable value?','unique records that cannot be replaced or priced precisely','a common item with a fixed low price','a small number easily counted','不可替代的档案价值难以估量。'),Q('incalculable',4,2,'An incalculable risk is one whose?','future consequences are difficult to foresee','exact result is already known','size is always zero','此义强调无法预测后果。')]);
P('incandescent','Incandescent 来自拉丁语 incandescere“变得白热、发光”，可形容炽热发白或明亮闪耀，也可比喻情绪极其强烈。',[C('incandescent.s1','光与温度','The metal wire became incandescent inside the bulb, glowing white as electric current heated it.','灯泡内的金属丝被电流加热后达到白热状态，发出白光。','The metal wire became incandescent inside the bulb / glowing white / as electric current heated it.','incandescent 描述物质热到发出白光；as 引出加热原因。','金属丝炽热发白，体现物理义。'),C('incandescent.s2','情绪与表达','The witness delivered an incandescent denunciation of the unsafe building, speaking with unmistakable anger.','证人以明显愤怒的语气强烈谴责那栋不安全建筑。','The witness delivered an incandescent denunciation / of the unsafe building / speaking with unmistakable anger.','incandescent 比喻情绪热烈、激昂；of 引出谴责对象。','明显愤怒的激烈谴责体现强烈情绪义。')],M('The wire glowed incandescently because it was cold, dark, and giving off no light.','The wire glowed incandescently because it was extremely hot and giving off bright light.','寒冷黑暗且不发光与白热发光相反。','word-choice'),[Q('incandescent',1,1,'Incandescent metal is?','so hot that it glows brightly','too cold to give off any light','made of a nonliving material only','s1 指炽热发光。'),Q('incandescent',2,2,'An incandescent denunciation is delivered with?','very strong feeling or anger','no emotion at all','careful silence','s2 比喻情绪激烈。'),Q('incandescent',3,1,'Why did the bulb wire glow white?','it became incandescent when heated','it became an inanimate object','it was kept in a dark drawer','加热使灯丝炽热发光。'),Q('incandescent',4,2,'Which speech could be called incandescent?','a forceful protest delivered with intense anger','a neutral list read without emotion','a quiet request for directions','强烈激昂的抗议符合比喻义。')]);
P('incapable','Incapable 由 in- 与 capable 构成，表示缺乏完成某事的能力，常用搭配 incapable of。',C('incapable.s1','能力与任务','The old tablet is incapable of running the new design software, so the studio assigned the task to a newer computer.','这台旧平板无法运行新的设计软件，因此工作室把任务交给了较新的电脑。','The old tablet is incapable of running the new design software / so the studio assigned the task / to a newer computer.','incapable of 后接动名词 running，表示设备缺乏运行软件的能力；so 引出替代安排。','旧设备不能运行该软件。'),M('The tablet is incapable of running the software because it opens the program quickly and completes every task.','The tablet is capable of running the software because it opens the program quickly and completes every task.','能够顺利运行软件，说明设备 capable，而非 incapable。','word-choice'),[Q('incapable',1,1,'A device incapable of running an app?','lacks the ability to run it','runs it perfectly every time','is in charge of its design','incapable 表示没有能力做某事。'),Q('incapable',2,1,'Why was the task moved to a newer computer?','the old tablet could not run the needed software','the old tablet ran it quickly','the software had already been removed from all devices','旧平板不能运行软件。'),Q('incapable',3,1,'Which construction is standard?','incapable of solving the problem','incapable to solving the problem','incapable for solve the problem','通常说 incapable of doing。'),Q('incapable',4,1,'Incapable is the opposite of?','capable','inadvertent','incessant','capable 表示有能力。')]);
P('incapacitate','Incapacitate 由 in-、capable 与动词后缀构成，表示使人受伤或虚弱到不能正常行动或工作。',C('incapacitate.s1','伤病与行动','A severe ankle injury incapacitated the goalkeeper, and a substitute took her place for the rest of the match.','严重的脚踝伤使守门员无法继续正常比赛，替补队员接替了她。','A severe ankle injury incapacitated the goalkeeper / and a substitute took her place / for the rest of the match.','incapacitate 表示使某人失去正常行动能力；and 引出替补应对。','受伤使守门员不能继续比赛。'),M('The ankle injury incapacitated the goalkeeper, allowing her to play the full match without difficulty.','The ankle injury incapacitated the goalkeeper, preventing her from playing normally.','不能正常比赛与轻松完成全场相矛盾。','word-choice'),[Q('incapacitate',1,1,'To incapacitate someone is to?','injure or weaken them so normal action is impossible','train them to perform better','put them in charge of a team','incapacitate 表示使不能正常行动。'),Q('incapacitate',2,1,'Why did the substitute enter the match?','the goalkeeper’s injury made her unable to continue','the goalkeeper scored every goal','the referee canceled the match','伤势使守门员无法继续。'),Q('incapacitate',3,1,'Which event may incapacitate a worker temporarily?','a serious injury that prevents normal movement','a routine break for lunch','a small increase in salary','严重伤势可能使人无法工作。'),Q('incapacitate',4,1,'Incapacitate is related to the adjective?','incapable','inarguably','in-depth','incapacitate 与 incapable 同根。')]);
P('incarcerate','Incarcerate 来自拉丁语 incarcerare，由 in-“进入”与 carcer“监狱”构成，指把人关进监狱或类似拘禁场所。',C('incarcerate.s1','司法与拘禁','The court may incarcerate a person only after a lawful conviction and a sentence consistent with local law.','只有在合法定罪并依当地法律判刑后，法院才可将人监禁。','The court may incarcerate a person / only after a lawful conviction / and a sentence consistent with local law.','incarcerate 表示监禁；only after 说明合法拘禁必须满足的程序条件。','句子将监禁限定于合法定罪和判刑之后。'),M('The court incarcerated the defendant by releasing him from custody and sending him home.','The court released the defendant from custody and sent him home.','释放回家是 incarcerate 的反义行为。','word-choice'),[Q('incarcerate',1,1,'To incarcerate a person is to?','confine them in a jail or similar place','appoint them to public office','help them move abroad','incarcerate 指监禁。'),Q('incarcerate',2,1,'Who may be incarcerated after a lawful conviction?','a person sentenced to confinement','a witness invited to give directions','a guard who is on duty','判刑后可能被关押的人会被监禁。'),Q('incarcerate',3,1,'Which word is closest to incarcerate?','imprison','inaugurate','inactivate','incarcerate 与 imprison 同义。'),Q('incarcerate',4,1,'The root carcer in incarcerate refers to?','a prison','a celebration','a flower ovule','词根 carcer 指监狱。')]);
P('incendiary','Incendiary 来自拉丁语 incendiarius、与 incendere“点燃”相关，可作形容词指纵火用的或煽动愤怒暴力的，也可作名词指燃烧弹、纵火者或煽动者。',[C('incendiary.s1','火灾与武器','Investigators found an incendiary device near the warehouse and evacuated the block before examining it.','调查人员在仓库附近发现一枚燃烧装置，于是先疏散街区再进行检查。','Investigators found an incendiary device / near the warehouse / and evacuated the block before examining it.','incendiary 修饰 device，表示用于引燃的；and 连接发现与安全处置。','发现会引发火灾的装置后先疏散。'),C('incendiary.s2','言论与冲突','The moderator removed an incendiary post that urged the crowd to attack a neighboring community.','版主删除了一条煽动性的帖子，因为它怂恿人群攻击邻近社区。','The moderator removed an incendiary post / that urged the crowd / to attack a neighboring community.','incendiary 比喻言论可能煽起愤怒或暴力；that 从句解释煽动内容。','帖子号召攻击他人，可能激起暴力。'),C('incendiary.s3','人物与称谓','The novel portrays the incendiary as a person who deliberately starts fires to frighten the town.','小说把纵火者描写成故意放火、恐吓镇民的人。','The novel portrays the incendiary / as a person who deliberately starts fires / to frighten the town.','incendiary 作名词指纵火者；who 从句说明其行为。','故意纵火的人符合该名词义。')],M('The post was incendiary because it calmly discouraged violence and urged everyone to settle the dispute peacefully.','The post was peaceable because it discouraged violence and urged everyone to settle the dispute calmly.','劝阻暴力的言论不是煽动性的。','word-choice'),[Q('incendiary',1,1,'An incendiary device is designed to?','start fires','put out a fire','measure a building','s1 指引燃或纵火用的装置。'),Q('incendiary',2,2,'An incendiary post may?','stir up anger or violence','calm every conflict','report a temperature accurately','s2 指煽动性言论。'),Q('incendiary',3,3,'An incendiary in a novel may be?','a person who deliberately starts fires','a person who repairs a roof','a person who holds a wedding','s3 可指纵火者。'),Q('incendiary',4,2,'Which message is incendiary?','one urging a crowd to attack its neighbors','one asking the crowd to remain peaceful','one giving neutral directions to a library','号召攻击邻人会煽动暴力。')]);
P('incense','Incense 作名词经古法语源自拉丁语 incensum“燃烧的东西”，指燃烧时散发香气的材料；作动词表示使人极为愤怒。',[C('incense.s1','香气与仪式','The temple burned sandalwood incense before the ceremony, filling the room with a gentle fragrance.','仪式开始前，寺庙点燃檀香，使房间里弥漫着柔和香气。','The temple burned sandalwood incense / before the ceremony / filling the room with a gentle fragrance.','incense 作名词指燃烧后散发香气的物质；before 表明焚香时间。','檀香燃烧后产生香气。'),C('incense.s2','愤怒与争执','It incensed the residents when the contractor blocked their only entrance without giving them notice.','承包商没有提前通知就堵住居民唯一的出入口，这让他们极为愤怒。','It incensed the residents / when the contractor blocked their only entrance / without giving them notice.','incense 作动词表示使某人极其愤怒；when 从句交代激怒原因。','堵住唯一通道且不通知居民引起强烈愤怒。')],M('The contractor’s unexplained blockade incensed the residents, meaning it made them completely calm and pleased.','The contractor’s unexplained blockade incensed the residents, meaning it made them extremely angry.','incense 作动词指激怒，不是使人平静愉快。','meaning'),[Q('incense',1,1,'Incense burned in a temple is?','a fragrant substance that gives off a smell when burned','a device that measures distance','a rule currently in force','s1 指燃烧时散香的物质。'),Q('incense',2,2,'A decision that incenses residents?','makes them extremely angry','makes them fall asleep','makes them feel in debt','s2 作动词意为激怒。'),Q('incense',3,1,'Which object is incense?','a stick burned to release fragrance','a metal ruler one inch long','a legal order in force','香条燃烧释放气味。'),Q('incense',4,2,'Why did blocking the only entrance incense residents?','it caused serious anger and inconvenience','it gave them a new entrance','it was an in-depth safety review','堵住出入口的行为使人愤怒。')]);
P('incentive','Incentive 来自拉丁语 incentivus，原与“激起、奏起”相关，现可指促使行动的因素、提供给人的奖励，或行动的诱因。',[C('incentive.s1','动机与行动','The chance to learn a new skill was an incentive for Mira to volunteer at the community workshop.','学习新技能的机会促使米拉到社区工坊做志愿者。','The chance to learn a new skill / was an incentive for Mira / to volunteer at the community workshop.','incentive 指鼓励行动的因素；to volunteer 说明它促使的行为。','学习机会成为米拉参加志愿活动的动力。'),C('incentive.s2','奖励与政策','The city offered a tax incentive to businesses that installed solar panels on their buildings.','市政府为在建筑物上安装太阳能板的企业提供税收优惠。','The city offered a tax incentive / to businesses / that installed solar panels on their buildings.','incentive 指鼓励特定行为的奖励措施；that 从句限定适用企业。','税收优惠旨在鼓励安装太阳能板。'),C('incentive.s3','诱因与原因','The lower fare was an incentive for commuters to switch from driving to the train.','较低票价促使通勤者从开车改乘火车。','The lower fare was an incentive for commuters / to switch / from driving to the train.','incentive 作诱因解释行为变化；to switch 说明它引发的行动。','低票价成为改乘火车的动机。')],M('The city offered a tax incentive to discourage businesses from installing solar panels.','The city offered a tax penalty to discourage businesses from installing solar panels.','鼓励措施与惩罚或阻止行为相反。','confusable'),[Q('incentive',1,1,'An incentive is something that?','encourages someone to act','prevents every possible action','confines a person in jail','incentive 指激励或鼓励。'),Q('incentive',2,2,'A tax incentive for solar panels is?','a reward or benefit offered to encourage installation','a fine imposed for using solar energy','a measurement of panel size','s2 指奖励措施。'),Q('incentive',3,3,'A lower train fare can be an incentive because it?','gives commuters a reason to switch from driving','forces everyone to leave the city','measures the distance to a station','s3 指促成行动的诱因。'),Q('incentive',4,1,'Which could be an incentive for learning?','access to a course that builds a useful skill','a rule banning every class','an unrelated inaccuracy','学习机会可以鼓励人参加课程。')]);
P('inception','Inception 来自拉丁语 inceptionem“开始、着手”，指某事物开始存在或启动的时刻。',C('inception.s1','项目与起源','From its inception, the neighborhood garden was planned as a shared space maintained by local families.','这个社区花园从创立之初就被规划成由当地家庭共同维护的共享空间。','From its inception / the neighborhood garden was planned / as a shared space maintained by local families.','from its inception 指从开始存在时起；maintained 修饰共享空间。','句子明确说明花园自建立时就有这一规划。'),M('The project’s inception was the moment it had already operated for ten years and was finally discontinued.','The project’s inception was the moment it began to exist.','项目开始存在的时刻才是 inception，不是十年后终止时。','meaning'),[Q('inception',1,1,'The inception of a project is?','the moment it begins to exist','the final report after it closes','the total cost of its equipment','inception 指开始。'),Q('inception',2,1,'“From its inception” means?','from the time it first began','only after it ended','instead of its original purpose','该短语意为从创立之初。'),Q('inception',3,1,'Which event marks a club’s inception?','the meeting where the club is first founded','the last meeting before it closes','a later anniversary dinner','成立会议标志社团创始。'),Q('inception',4,1,'Inception is closest in meaning to?','beginning','inactivity','inaccuracy','inception 与 beginning 接近。')]);
P('incessant','Incessant 来自拉丁语 incessans、含“不停止”之意，形容持续不断、往往令人厌烦的事物。',C('incessant.s1','持续噪音','The tenants complained about incessant drilling from the renovation site, which continued from dawn until evening.','住户抱怨装修工地的钻孔声接连不断，从清晨持续到傍晚。','The tenants complained about incessant drilling / from the renovation site / which continued from dawn until evening.','incessant 修饰 drilling，强调持续不停且令人烦扰；which 从句补充持续时段。','噪声从早到晚不停，符合 incessant。'),M('The tenants described the drilling as incessant even though it lasted for one brief minute and never returned.','The tenants described the drilling as brief because it lasted for one minute and never returned.','短暂且只发生一次的噪音不是持续不断。','word-choice'),[Q('incessant',1,1,'Incessant noise is noise that?','continues without stopping, often annoyingly','occurs once and ends immediately','is too quiet to hear','incessant 指接连不断。'),Q('incessant',2,1,'Why did tenants complain about drilling?','it continued from dawn until evening','it lasted for one brief minute','it happened before they moved in and never returned','长时间不停的噪音令人烦扰。'),Q('incessant',3,1,'Which event could be called incessant?','a phone ringing repeatedly without a pause','one knock at the door','a bell that never sounds','反复不停的铃声符合该词。'),Q('incessant',4,1,'Incessant is closest in meaning to?','unceasing','inadvertent','inborn','incessant 意为持续不停的。')]);
P('incessantly','Incessantly 由 incessant 加副词后缀 -ly 构成，表示没有停顿或休息地持续进行。',C('incessantly.s1','重复行动','The neighbor’s dog barked incessantly during the storm, keeping several families awake through the night.','暴风雨期间，邻居家的狗不停地吠叫，附近几户人家整夜无法入睡。','The neighbor’s dog barked incessantly during the storm / keeping several families awake / through the night.','incessantly 修饰 barked，表示持续不断；keeping 补充结果。','狗叫声持续整夜。'),M('The alarm sounded incessantly because it rang once and then remained silent for the rest of the day.','The alarm sounded briefly because it rang once and then remained silent for the rest of the day.','只响一次后保持安静，不是 incessantly。','word-choice'),[Q('incessantly',1,1,'To speak incessantly is to speak?','continuously without a pause','only once and then stop','with a hidden purpose','incessantly 表示不停地。'),Q('incessantly',2,1,'Why were families awake?','the dog barked throughout the night','the dog barked once at noon','the storm was canceled','整夜不停的犬吠打扰了邻居。'),Q('incessantly',3,1,'Which action happens incessantly?','a machine beeping again and again without stopping','a single bell chime','a light that stays off','持续不断的提示音符合该副词。'),Q('incessantly',4,1,'Incessantly is the adverb form of?','incessant','incentive','incapable','incessantly 由 incessant 派生。')]);
P('inch','Inch 源自古英语 ynce、与拉丁语 uncia“十二分之一”相关，名词指2.54厘米的长度单位或极小距离，作动词指缓慢谨慎地一点点移动。',[C('inch.s1','长度单位','The carpenter cut the shelf to exactly twelve inches so it would fit between the two cabinets.','木匠把搁板精确锯成十二英寸，使它能装进两个柜子之间。','The carpenter cut the shelf to exactly twelve inches / so it would fit / between the two cabinets.','inch 作名词指长度单位；so 引出切割尺寸的目的。','十二英寸是用于量取搁板长度的单位。'),C('inch.s2','微小距离','The hikers moved forward an inch at a time along the narrow ledge, keeping one hand on the rock wall.','徒步者沿着狭窄岩架一次只向前挪一点点，一只手始终扶着岩壁。','The hikers moved forward an inch at a time / along the narrow ledge / keeping one hand on the rock wall.','an inch 可比喻极小距离；at a time 表示每次前进的幅度。','每次前进一点点，体现小距离义。'),C('inch.s3','缓慢移动','The heavy cabinet inched across the floor as two movers pushed it carefully toward the doorway.','两名搬运工小心地推着沉重柜子，让它沿地板一点点挪向门口。','The heavy cabinet inched across the floor / as two movers pushed it carefully / toward the doorway.','inch 作动词表示缓慢谨慎地移动；as 从句说明移动方式。','柜子缓慢一点点地滑向门口。')],M('The heavy cabinet inched across the room by leaping instantly from the doorway to the opposite wall.','The heavy cabinet moved slowly across the room a little at a time.','瞬间跳到另一处不是缓慢渐进地移动。'),[Q('inch',1,1,'One inch is equal to?','2.54 centimetres','one metre','twelve feet','一英寸等于2.54厘米。'),Q('inch',2,2,'If hikers move an inch at a time, they move?','a very small distance on each step','a full mile on each step','without moving at all','s2 指很小的距离。'),Q('inch',3,3,'To inch a cabinet toward a doorway is to?','move it slowly and carefully a little at a time','carry it instantly across the building','measure its weight in pounds','inch 作动词表示一点点缓慢移动。'),Q('inch',4,1,'Which sentence uses inch as a unit?','The board is 24 inches long.','The board inched slowly toward the door.','The board was incessant.','第一个句子中 inch 是长度单位。')]);

})();
